//! Smoke tests for the language core. These are the fast inner loop while growing the engine; the
//! broad conformance signal comes from `crates/test262-runner`.

#[cfg(feature = "embed")]
use crate::embed::{Ctx, Value};
#[cfg(feature = "embed")]
use crate::scope::ValueKind;
use crate::value::ValueView;
use crate::{Completion, Engine, ExecutionOutcome, InterruptReason};

/// The completion value of `src` in the scope `cx`, with no microtask checkpoint.
#[cfg(feature = "embed")]
fn value_in<'s>(cx: &mut Ctx<'s>, src: &str) -> Value<'s> {
    cx.eval_value_interruptible(src)
        .expect("fixture parses")
        .unwrap_or_else(|_| panic!("fixture threw: {src}"))
}

/// ToString of a value of the scope `cx`, as Rust text.
#[cfg(feature = "embed")]
fn text_of<'s>(cx: &mut Ctx<'s>, value: &Value<'s>) -> String {
    cx.coerce_string(value)
        .unwrap_or_else(|_| panic!("ToString threw"))
        .to_string()
}

/// Run `src` in a scope of `engine`, with no microtask checkpoint.
#[cfg(feature = "embed")]
fn eval_quiet(engine: &mut Engine, src: &str) {
    engine.scope(|cx| {
        value_in(cx, src);
    });
}

/// `src` evaluated as a classic Script in a scope of `engine` (`Ctx::eval_classic_script_interruptible`):
/// `Err("throw")` when it threw, `Err("interrupted")` when it was interrupted.
#[cfg(feature = "embed")]
fn classic(engine: &mut Engine, src: &str) -> Result<(), &'static str> {
    engine.scope(|cx| match cx.eval_classic_script_interruptible(src) {
        Ok(Ok(_)) => Ok(()),
        Ok(Err(crate::embed::EvalError::Throw(_))) => Err("throw"),
        Ok(Err(crate::embed::EvalError::Interrupted(_))) => Err("interrupted"),
        Err(error) => panic!("classic script did not parse: {}", error.message),
    })
}

/// The `(context, reason)` of taken rejections whose reasons are numbers, read in a scope.
#[cfg(feature = "embed")]
fn reasons(
    engine: &mut Engine,
    taken: &[(u64, crate::embed::Handle, crate::embed::Handle)],
) -> Vec<(u64, f64)> {
    engine.scope(|cx| {
        taken
            .iter()
            .filter_map(|(context, _, reason)| Some((*context, reason.get(cx).ok()?.as_num_opt()?)))
            .collect()
    })
}

/// Whether `src`, run in a scope of `engine` with no microtask checkpoint, is `true`.
#[cfg(feature = "embed")]
fn eval_true(engine: &mut Engine, src: &str) -> bool {
    engine.scope(|cx| matches!((value_in(cx, src)).kind(), ValueKind::Bool(true)))
}

fn run(src: &str) -> String {
    match Engine::new().eval(src, false).expect("parse") {
        Completion::Value(v) => v,
        Completion::Throw { name, message } => panic!("threw {name}: {message}"),
    }
}

fn run_in(engine: &mut Engine, src: &str) -> String {
    match engine.eval(src, false).expect("parse") {
        Completion::Value(v) => v,
        Completion::Throw { name, message } => panic!("threw {name}: {message}"),
    }
}

fn throws(src: &str) -> String {
    match Engine::new().eval(src, false).expect("parse") {
        Completion::Value(v) => panic!("expected throw, got {v}"),
        Completion::Throw { name, .. } => name,
    }
}

#[test]
fn arithmetic() {
    assert_eq!(run("1 + 2 * 3"), "7");
    assert_eq!(run("2 ** 10"), "1024");
    assert_eq!(run("7 % 3"), "1");
    assert_eq!(run("'a' + 'b' + 1"), "ab1");
}

#[test]
fn integer_switch_dispatch_preserves_case_block_semantics_in_all_tiers() {
    // ECMA-262 CaseBlockEvaluation, CaseClauseIsSelected and strict equality,
    // snapshot e28783d5fc9d. Include defaults before later matches and duplicate ±0.
    let source = r#"
        function check(ok, message) {if (!ok) throw new Error(message);}
        function select(v) {
            var out = '';
            switch (v) {
                case -2147483648: return 'min';
                case -3: return 'minus';
                case -0: out += 'zero'; break;
                case 0: return 'duplicate';
                case 1: out += 'one';
                default: out += 'default';
                case 7: out += 'seven'; break;
                case 12: return 'twelve';
                case 101: return 'hundred';
                case 4096: return 'large';
                case 2147483647: return 'max';
            }
            return out;
        }
        var conversions = 0;
        var object = {valueOf() {conversions++; return 7;}};
        for (var warm = 0; warm < 50; ++warm) {
            check(select(0) === 'zero' && select(-0) === 'zero', 'first duplicate');
            check(select(1) === 'onedefaultseven', 'source order fallthrough');
            check(select(7) === 'seven', 'match after default');
            check(select(-3) === 'minus' && select(12) === 'twelve', 'sparse integers');
            check(select(-2147483648) === 'min' && select(2147483647) === 'max', 'boundaries');
        }
        for (var v of [NaN, Infinity, -Infinity, 0.5, -1, 102, '7', true,
                        undefined, null, 7n, Symbol(), object])
            check(select(v) === 'defaultseven', 'strict equality and misses');
        check(conversions === 0, 'no discriminant coercion');
        function lexical(v) {
            switch (v) {
                case 1: return later();
                case 2: case 3: case 4: case 5: case 6: case 7: case 8: return 0;
                default: function later() {return 42;}
            }
        }
        check(lexical(1) === 42, 'shared lexical instantiation');
        var trace = [];
        function test(v) {trace.push(v); return v;}
        function dynamic(v) {
            switch (v) {
                case test(0): case test(1): return 'before';
                default: return 'default';
                case test(2): return 'after';
                case test(3): return 'last';
            }
        }
        check(dynamic(2) === 'after' && trace.join() === '0,1,2', 'ordered dynamic tests');
        'ok'
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(run_in(&mut engine, source), "ok", "tier {tier:?}");
    }
}

#[test]
fn boolean_bitwise_fast_paths_preserve_numbers_and_coercion_in_all_tiers() {
    // Boolean execution values carry their scalar payload in the canonical eight-byte word.
    for boolean in [false, true] {
        let value = crate::value::Value::Bool(boolean);
        assert_eq!(std::mem::size_of_val(&value), 8);
        assert_eq!(value.bits(), crate::value::PACK_BOOL | u64::from(boolean));
    }
    // ECMA-262 ToNumeric, ToNumber, ApplyStringOrNumericBinaryOperator, snapshot e28783d5fc9d.
    // Comparisons feeding a bitwise mask are common in generated asm.js initialization loops.
    let source = r#"
        function check(ok, message) { if (!ok) throw new Error(message); }
        function mask(a, b) { return a & b; }
        function bits(a, b) { return [a & b, a | b, a ^ b, a << b, a >> b, a >>> b]; }
        function loop(n) {
            var sum = 0;
            for (var k = 0; k < n; ++k) sum = (sum + ((k > 0) & (k < n - 1))) | 0;
            return sum;
        }
        for (var warm = 0; warm < 150; ++warm) {
            check(mask(true, false) === 0 && mask(true, true) === 1, 'boolean result is Number');
            check(loop(20) === 18, 'comparison mask');
            bits(warm, warm + 1);
        }
        const values = [false, true, 0, -0, 3.9, -3.9, 2147483647, 2147483648,
                        4294967295, 4294967296, 2 ** 63, -(2 ** 63), 1e100,
                        NaN, Infinity, -Infinity, null, undefined, '7'];
        for (const a of values) for (const b of values) {
            const actual = bits(a, b), expected = bits(Number(a), Number(b));
            for (let k = 0; k < actual.length; ++k)
                check(Object.is(actual[k], expected[k]), 'primitive conversion ' + k);
        }
        const trace = [];
        const left = {valueOf() {trace.push('left'); return true;}};
        const right = {valueOf() {trace.push('right'); return 7;}};
        check(mask(left, right) === 1 && trace.join(',') === 'left,right', 'ordered coercion');
        trace.length = 0;
        check(mask(true, right) === 1 && trace.join(',') === 'right', 'mixed primitive/object');
        trace.length = 0;
        try {mask(Symbol(), right); check(false, 'must throw');}
        catch (e) {check(e instanceof TypeError && trace.length === 0, 'left throws first');}
        for (const pair of [[true, 1n], [1n, false]]) {
            try {bits(pair[0], pair[1]); check(false, 'mixed BigInt must throw');}
            catch (e) {check(e instanceof TypeError, 'BigInt type error');}
        }
        check(mask(3n, 1n) === 1n, 'BigInt preserved');
        'ok'
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(run_in(&mut engine, source), "ok", "tier {tier:?}");
    }
}

#[test]
fn numeric_typed_array_access_preserves_exotic_semantics_in_all_tiers() {
    // ECMA-262 ToPropertyKey, TypedArray [[Get]]/[[Set]], TypedArraySetElement and
    // IsValidIntegerIndex, local snapshot e28783d5fc9d. Exercise the shared numeric-index
    // fast path as well as the conversion/Proxy/immutable fallbacks it must not consume.
    let source = r#"
        function check(ok, message) { if (!ok) throw new Error(message); }
        function get(a, k) { return a[k]; }
        function set(a, k, v) { return a[k] = v; }
        function inc(a, k) { return a[k]++; }
        for (const C of [Int8Array, Uint8Array, Uint8ClampedArray, Int16Array,
                         Uint16Array, Int32Array, Uint32Array, Float32Array, Float64Array]) {
            const a = new C(4);
            for (let warm = 0; warm < 120; ++warm) {
                check(set(a, 1, 42) === 42 && get(a, 1) === 42, 'read/write');
                check(inc(a, 1) === 42 && get(a, 1) === 43, 'update');
            }
            for (const v of [-2147483649, -2147483648, -65537, -129, -1, -0,
                             0.5, 1.5, 2.5, 127, 128, 255, 256, 65535, 65536,
                             2147483647, 2147483648, 4294967295, 4294967296,
                             1e100, NaN, Infinity, -Infinity, 1 + 2 ** -24]) {
                const expected = new C([v])[0];
                check(Object.is(set(a, 1, v), v), 'assignment keeps original Number');
                check(Object.is(get(a, 1), expected), 'element conversion ' + C.name);
            }
            set(a, -0, 7);
            check(get(a, 0) === 7 && get(a, -0) === 7, 'numeric negative zero');
            set(a, '-0', 99);
            check(get(a, '-0') === undefined && get(a, 0) === 7, 'string negative zero');
            for (const key of [-1, 1.5, NaN, Infinity, 4, 4294967295]) {
                check(set(a, key, 123) === 123 && get(a, key) === undefined, 'invalid index');
                check(!Object.hasOwn(a, String(key)), 'invalid index is not an own property');
            }
            let conversions = 0;
            set(a, 4, { valueOf() { ++conversions; return 9; } });
            check(conversions === 1, 'out of bounds still coerces value');
            for (const key of [0, 4]) {
                let threw = false;
                try { set(a, key, 1n); } catch (e) { threw = e instanceof TypeError; }
                check(threw, 'Number content rejects BigInt even out of bounds');
            }
        }
        for (const C of [BigInt64Array, BigUint64Array]) {
            const a = new C(2);
            set(a, 0, 12n);
            check(get(a, 0) === 12n && inc(a, 0) === 12n && get(a, 0) === 13n, 'BigInt access');
            for (const key of [0, 2]) {
                let threw = false;
                try { set(a, key, 1); } catch (e) { threw = e instanceof TypeError; }
                check(threw, 'BigInt content rejects Number even out of bounds');
            }
        }
        const rab = new ArrayBuffer(8, { maxByteLength: 16 });
        const tracking = new Uint8Array(rab, 2), fixed = new Uint8Array(rab, 2, 4);
        set(fixed, 0, 21);
        rab.resize(4);
        check(get(fixed, 0) === undefined && get(tracking, 0) === 21, 'shrunken view bounds');
        set(fixed, 0, 99);
        check(get(tracking, 0) === 21, 'out of bounds fixed view cannot write');
        rab.resize(12);
        set(tracking, 9, 33);
        check(get(fixed, 0) === 21 && get(tracking, 9) === 33, 'regrown views');
        set(tracking, 0, { valueOf() { rab.transfer(); return 9; } });
        check(get(tracking, 0) === undefined, 'detach during conversion');
        set(tracking, 0, 8);
        check(get(tracking, 0) === undefined, 'detached write is inert');
        const target = new Uint8Array(2), trace = [];
        const proxy = new Proxy(target, {
            get(t, k) { trace.push('get:' + k); return 17; },
            set(t, k, v) { trace.push('set:' + k); return true; }
        });
        set(proxy, 0, 7);
        check(get(proxy, 0) === 17 && target[0] === 0, 'Proxy traps preserved');
        check(trace.join(',') === 'set:0,get:0', 'Proxy key conversions');
        const receiver = {};
        Reflect.set(target, '0', 55, receiver);
        check(receiver[0] === 55 && target[0] === 0, 'different receiver');
        const immutable = new Uint8Array(new ArrayBuffer(2).transferToImmutable());
        let threw = false;
        try { (function () { 'use strict'; immutable[0] = 1; })(); }
        catch (e) { threw = e instanceof TypeError; }
        check(threw && get(immutable, 0) === 0, 'immutable writes');
        const shared = new Int32Array(new SharedArrayBuffer(8));
        set(shared, 1, 123);
        check(get(shared, 1) === 123 && Atomics.load(shared, 1) === 123, 'shared storage');
        'ok'
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(run_in(&mut engine, source), "ok", "tier {tier:?}");
    }
}

/// `length`, `byteLength`, `byteOffset` and `buffer` are %TypedArray.prototype% accessors and
/// BYTES_PER_ELEMENT a prototype data property: a TypedArray's [[Get]] answers them directly only
/// where OrdinaryGet would reach those intrinsics, and own properties of those names are
/// ordinary own properties. Expected values are node's.
#[test]
fn typed_array_accessor_reads_follow_the_prototype_chain_in_all_tiers() {
    let source = r#"
        var out = [];
        function t(f) { try { out.push(String(f())); } catch (e) { out.push(e.constructor.name); } }
        class V extends Float32Array {
            get length() { return 99; } get byteLength() { return 98; }
            get byteOffset() { return 97; } get buffer() { return 'buf'; } }
        var v = new V(4);
        t(function () { return [v.length, v.byteLength, v.byteOffset, v.buffer, v.BYTES_PER_ELEMENT]; });
        var orphan = Object.setPrototypeOf(new Int16Array(2), null);
        t(function () { return [orphan.length, orphan.byteLength, orphan.buffer, orphan.BYTES_PER_ELEMENT]; });
        var u = new Uint8Array(3), f = new Float64Array(3);
        t(function () { return [u.length, u.byteLength, u.byteOffset, u.buffer instanceof ArrayBuffer]; });
        t(function () { return Reflect.get(u, 'length', f) + '/' + Reflect.get(u, 'byteLength', f); });
        t(function () { return Reflect.get(u, 'length', {}); });
        t(function () { return Object.create(u).length; });
        var TAP = Object.getPrototypeOf(Uint8Array.prototype);
        var lengthGet = Object.getOwnPropertyDescriptor(TAP, 'length');
        var byteLengthGet = Object.getOwnPropertyDescriptor(TAP, 'byteLength').get;
        Object.defineProperty(TAP, 'length', {
            get() { return 'patched:' + lengthGet.get.call(this); }, configurable: true });
        t(function () { return u.length + '/' + new Float64Array(2).length; });
        Object.defineProperty(TAP, 'length', lengthGet);
        class S extends Int16Array {}
        Object.defineProperty(S.prototype, 'length', { get: byteLengthGet });
        Object.defineProperty(S.prototype, 'BYTES_PER_ELEMENT', { value: 's' });
        t(function () { return new S(5).length + '/' + new S(1).BYTES_PER_ELEMENT; });
        Object.defineProperty(Uint16Array.prototype, 'byteLength', { value: 'own-data' });
        t(function () { return new Uint16Array(4).byteLength; });
        var proxied = Object.setPrototypeOf(new Int8Array(5),
            new Proxy({}, { get(target, key) { return 'proxy:' + String(key); } }));
        t(function () { return proxied.length + '/' + proxied.byteOffset; });
        var z = new Int8Array(2);
        Object.defineProperty(z, 'length', { value: 9, enumerable: true, configurable: true });
        Object.defineProperty(z, 'buffer', { value: 8, enumerable: false, configurable: true });
        z.extra = 1;
        t(function () { return [z.length, z.buffer, Object.keys(z).join('/'),
            Object.getOwnPropertyNames(z).join('/'), JSON.stringify(Object.entries(z))].join(' '); });
        function hot(a) { var s = 0; for (var i = 0; i < 300; i++) s += a.length + a.byteLength; return s; }
        t(function () { return [hot(new Uint8Array(2)), hot(v), hot(orphan)].join('/'); });
        // Changes after warm reads: a concrete prototype's own accessor, its [[Prototype]], and
        // the intrinsic holder's keys.
        function last(a, key) { var r; for (var i = 0; i < 300; i++) r = a[key]; return r; }
        var w = new Int32Array(2);
        hot(w);
        Object.defineProperty(Int32Array.prototype, 'length', {
            get() { return 'concrete'; }, configurable: true });
        t(function () { return w.length + '/' + last(w, 'length'); });
        delete Int32Array.prototype.length;
        Object.setPrototypeOf(Int32Array.prototype, null);
        t(function () { return w.length + '/' + last(w, 'buffer'); });
        Object.setPrototypeOf(Int32Array.prototype, TAP);
        var byteOffsetDesc = Object.getOwnPropertyDescriptor(TAP, 'byteOffset');
        delete TAP.byteOffset;
        t(function () { return w.byteOffset + '/' + last(w, 'length'); });
        Object.defineProperty(TAP, 'byteOffset', byteOffsetDesc);
        t(function () { return last(w, 'byteOffset') + '/' + hot(w); });
        out.join(';')
    "#;
    let expected = "99,98,97,buf,4;,,,;3,3,0,true;3/24;TypeError;TypeError;patched:3/patched:2;\
        10/s;own-data;proxy:length/proxy:byteOffset;\
        9 8 0/1/length/extra 0/1/length/buffer/extra [[\"0\",0],[\"1\",0],[\"length\",9],[\"extra\",1]];\
        1200/59100/NaN;concrete/concrete;undefined/undefined;undefined/2;0/3000";
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(run_in(&mut engine, source), expected, "tier {tier:?}");
    }
}

#[cfg(feature = "embed")]
#[test]
fn fragmented_array_buffer_writes_preserve_host_synchronization() {
    let mut engine = Engine::new();
    run_in(
        &mut engine,
        "var buffer = new ArrayBuffer(4096); var bytes = new Uint8Array(buffer)",
    );
    engine.scope(|cx| {
        let buffer = value_in(cx, "buffer");
        let version = cx.array_buffer_version(&buffer).unwrap();
        value_in(cx, "for (var i = 0; i < 1024; ++i) bytes[i * 4] = i & 255");
        assert_ne!(cx.array_buffer_version(&buffer), Some(version));
        let ranges = cx.take_array_buffer_dirty_ranges(&buffer).unwrap();
        assert_eq!(ranges.len(), 1);
        assert_eq!(ranges[0], 0..4096);
        let mut mirror = vec![0; 4096];
        for range in ranges {
            assert!(cx.array_buffer_copy_range(
                &buffer,
                range.start,
                range.len(),
                &mut mirror[range]
            ));
        }
        for index in 0..1024 {
            assert_eq!(mirror[index * 4], (index & 255) as u8);
        }
        assert!(cx
            .take_array_buffer_dirty_ranges(&buffer)
            .unwrap()
            .is_empty());
        // Host writes are not echoed as JS mutations; precise tracking resumes after taking.
        let version = cx.array_buffer_version(&buffer).unwrap();
        assert!(cx.array_buffer_set_range(&buffer, 3, &[17]));
        assert_eq!(cx.array_buffer_version(&buffer), Some(version));
        value_in(cx, "bytes[5] = 42; new DataView(buffer).setUint16(7, 256)");
        assert_eq!(
            cx.take_array_buffer_dirty_ranges(&buffer).unwrap(),
            [5..6, 7..9]
        );
    });
    assert_eq!(
        run_in(&mut engine, "bytes[3] + ',' + bytes[5] + ',' + bytes[7]"),
        "17,42,1"
    );
}

/// The embedder mirror API (mutation generations, dirty ranges, range reads and writes) covers
/// ordinary ArrayBuffers only. A SharedArrayBuffer is rejected like a detached buffer: it used
/// to report a generation that never changed and no dirty ranges however JavaScript wrote it,
/// and accepted empty reads and writes as if it were an empty ordinary buffer.
#[test]
fn array_buffer_mirror_api_rejects_shared_array_buffers() {
    let mut engine = Engine::new();
    run_in(
        &mut engine,
        "var sab = new SharedArrayBuffer(8), empty = new SharedArrayBuffer(0);
         var ordinary = new ArrayBuffer(8); new Uint8Array(sab)[3] = 9",
    );
    let read = |engine: &mut Engine, name: &str| {
        let global = engine.interp.global.borrow();
        global.props.get(name).expect("global binding").value()
    };
    let (sab, empty, ordinary) = (
        read(&mut engine, "sab"),
        read(&mut engine, "empty"),
        read(&mut engine, "ordinary"),
    );
    for buffer in [&sab, &empty] {
        assert_eq!(engine.interp.array_buffer_version(buffer), None);
        assert_eq!(engine.interp.take_array_buffer_dirty_ranges(buffer), None);
        assert!(!engine.interp.array_buffer_set_bytes(buffer, &[]));
        assert!(!engine.interp.array_buffer_set_range(buffer, 0, &[]));
        assert!(!engine.interp.array_buffer_copy_range(buffer, 0, 0, &mut []));
    }
    assert!(!engine.interp.array_buffer_set_bytes(&sab, &[1; 8]));
    assert_eq!(
        engine.interp.buffer_source_bytes(&sab, true),
        Some(vec![0, 0, 0, 9, 0, 0, 0, 0])
    );
    assert_eq!(engine.interp.array_buffer_version(&ordinary), Some(0));
    assert!(engine.interp.array_buffer_set_bytes(&ordinary, &[1; 8]));
    run_in(&mut engine, "new Uint8Array(ordinary)[2] = 5");
    assert_eq!(engine.interp.array_buffer_version(&ordinary), Some(1));
    assert_eq!(
        engine.interp.take_array_buffer_dirty_ranges(&ordinary),
        Some(std::iter::once(2..3).collect())
    );
}

#[test]
fn global_declaration_property_order_follows_instantiation_order() {
    // ECMA-262 GlobalDeclarationInstantiation: Annex B-only bindings first,
    // surviving function declarations in source order, then first-seen vars.
    let source = r#"
        var order61_z = 1, order61_existing;
        function order61_fa() { return 0; }
        var [order61_a, order61_b] = [2, 3];
        if (false) { function order61_block() {} }
        function order61_fb() { return 4; }
        var order61_fa, order61_z;
        function order61_fa() { return 5; }
        for (var order61_c = 0; order61_c < 1; order61_c++) {}
        { var order61_late = 6; }
        let order61_lexical = 7;
        Object.keys(globalThis).filter(k => k.startsWith('order61_')).join(',')
          + '|' + order61_fa() + '|' + order61_existing
          + '|' + Object.getOwnPropertyDescriptor(globalThis, 'order61_z').configurable
          + '|' + Object.getOwnPropertyDescriptor(globalThis, 'order61_existing').configurable
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        run_in(&mut engine, "globalThis.order61_existing = 17");
        assert_eq!(
            run_in(&mut engine, source),
            "order61_existing,order61_block,order61_fb,order61_fa,order61_z,order61_a,order61_b,order61_c,order61_late|5|17|false|true",
            "tier {tier:?}"
        );
    }
}

#[test]
fn eval_global_declaration_property_order_preserves_last_function_and_first_var() {
    // EvalDeclarationInstantiation has the same order, but new global
    // properties are configurable. Both direct and indirect sloppy eval apply.
    let body = r#"
        var order61_z = 1;
        function order61_fa() { return 0; }
        var order61_a = 2, order61_z;
        if (false) { function order61_block() {} }
        function order61_fb() { return 4; }
        function order61_fa() { return 5; }
        Object.keys(globalThis).filter(k => k.startsWith('order61_')).join(',')
          + '|' + order61_fa()
          + '|' + Object.getOwnPropertyDescriptor(globalThis, 'order61_z').configurable
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        for callee in ["eval", "(0, eval)"] {
            let mut engine = Engine::new();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                run_in(&mut engine, &format!("{callee}({body:?})")),
                "order61_block,order61_fb,order61_fa,order61_z,order61_a|5|true",
                "tier {tier:?}, callee {callee}"
            );
        }
    }
}

#[test]
fn with_proxy_get_binding_value_rechecks_has_property() {
    // Object Environment Record.HasBinding and GetBindingValue each perform
    // HasProperty. Do not fuse the calls: the Proxy may change its answer.
    let source = r#"
        let log = [], checks = 0, result = 99;
        const object = new Proxy({p: 42}, {
            has(target, key) {
                if (key === 'p') { log.push('has'); return ++checks === 1; }
                return Reflect.has(target, key);
            },
            get(target, key) {
                if (key === Symbol.unscopables) log.push('unscopables');
                if (key === 'p') log.push('get');
                return Reflect.get(target, key);
            }
        });
        with (object) { result = p; }
        log.join(',') + '|' + String(result)
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(&mut engine, source),
            "has,unscopables,has|undefined",
            "tier {tier:?}"
        );
    }
}

#[test]
fn fresh_closure_code_reuse_preserves_identity_environment_and_abrupt_completion() {
    // ECMA-262 PrepareForOrdinaryCall/OrdinaryFunctionCreate: sharing executable code
    // must not reuse the old closure's Function, [[Environment]], or [[Realm]].
    let source = r#"
        function invoke(f, x) { return f(x); }
        function identity() { try { return identity.caller; } catch (error) { throw error; } }
        function make(value) {
            return function (x) {
                try {
                    if (x < 0) throw value;
                    return [value + x, identity()];
                } catch (error) { throw error; }
            };
        }
        let total = 0;
        for (let i = 0; i < 600; i++) {
            let f = make(i);
            let result = invoke(f, 1);
            if (result[1] !== f || result[0] !== i + 1)
                throw 'stale closure at ' + i + ': value=' + result[0] + ', identity=' + (result[1] === f);
            try { invoke(f, -1); throw 'missing throw'; }
            catch (error) { if (error !== i) throw 'wrong abrupt completion'; }
            total += result[0];
        }
        let proxyCalls = 0;
        const p = new Proxy(make(1000), {apply(f, t, a) { proxyCalls++; return Reflect.apply(f,t,a); }});
        if (invoke(p, 2)[0] !== 1002 || proxyCalls !== 1) throw 'proxy bypass';
        const revoked = Proxy.revocable(make(0), {});
        revoked.revoke();
        try { invoke(revoked.proxy, 1); throw 'missing revocation'; }
        catch (e) { if (!(e instanceof TypeError)) throw e; }
        const other = $262.createRealm().global;
        other.eval('globalThis.make = function(v) { return function(x) { return [v+x, new TypeError()]; }; };');
        for (let i = 0; i < 150; i++) {
            const f = other.make(i);
            const r = invoke(f, 3);
            if (r[0] !== i + 3 || !(r[1] instanceof other.TypeError) || r[1] instanceof TypeError)
                throw 'wrong realm';
        }
        total
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(run_in(&mut engine, source), "180300", "{tier:?}");
    }
}

#[test]
fn megamorphic_calls_preserve_receivers_arguments_closures_and_throws() {
    // ECMA-262 [[Call]], PrepareForOrdinaryCall and OrdinaryCallBindThis: a cached target's
    // identity never substitutes for the current arguments, receiver or closure environment.
    let source = r#"
        var boxes = [];
        for (var k = 0; k < 16; k++) {
            var make = Function('captured', 'return function(a,b){' +
                (k & 1 ? '"use strict";' : '') +
                'if(a.fail) throw a; var before=arguments[0]; a=b;' +
                'var inner=function(){return a;};' +
                'return [this,captured,before,arguments[0],arguments.length,new.target,inner()];};');
            boxes.push({run: make(k)});
        }
        function dispatch(box, a, b) { return box.run(a, b); }
        function bare(fn, a, b) { return fn(a, b); }
        var a = {tag:'first'}, b = {tag:'second'};
        function verify() {
            for (var k = 0; k < boxes.length; k++) {
                var r = dispatch(boxes[k], a, b);
                if(r[0]!==boxes[k] || r[1]!==k || r[2]!==a ||
                   r[3]!==((k&1)?a:b) || r[4]!==2 || r[5]!==undefined || r[6]!==b)
                    throw 'method state ' + k;
                r = bare(boxes[k].run, a, b);
                if(r[0]!==((k&1)?undefined:globalThis) || r[1]!==k) throw 'bare state ' + k;
            }
        }
        for(var round=0; round<160; round++) verify();
        function leaf(v){return v+1;} function driver(v){return leaf(v);}
        function outer(v){return driver(v);} for(var k=0;k<400;k++) outer(k);
        verify(); // A separate inline recompile invalidated the old call epoch.
        var thrown = {fail:true};
        for(var k=0;k<boxes.length;k++) {
            try {dispatch(boxes[k], thrown, b); throw 'missing throw';}
            catch(e){if(e!==thrown) throw 'wrong exception';}
        }
        var traps = 0;
        var proxy = new Proxy(boxes[0].run, {apply(f,t,args){traps++;return Reflect.apply(f,t,args);}});
        boxes[0].run = proxy;
        if(dispatch(boxes[0],a,b)[0]!==boxes[0] || traps!==1) throw 'proxy bypass';
        var revoked = Proxy.revocable(boxes[1].run, {}); revoked.revoke();
        boxes[1].run = revoked.proxy;
        try {dispatch(boxes[1],a,b);throw 'missing revocation';}
        catch(e){if(!(e instanceof TypeError))throw e;}
        boxes[2].run = class NotCallable {};
        try {dispatch(boxes[2],a,b);throw 'called class';}
        catch(e){if(!(e instanceof TypeError))throw e;}
        'ok'
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(run_in(&mut engine, source), "ok", "{tier:?}");
    }
}

#[test]
fn megamorphic_calls_preserve_native_and_user_realms() {
    let source = r#"
        var other = $262.createRealm().global;
        var natives = [Math.abs, Math.floor, Math.ceil, Number, parseFloat, parseInt, String, Boolean];
        var expected = [3.5,3,4,3.5,3.5,3,'3.5',true];
        function dispatch(f,x){return f(x);}
        for(var round=0;round<200;round++) for(var k=0;k<natives.length;k++) {
            if(dispatch(natives[k],3.5)!==expected[k])throw 'native dispatch';
        }
        var local = [], foreign = [];
        for(var k=0;k<16;k++) {
            local.push(Function('x','return [x+'+k+',new TypeError(),this];'));
            foreign.push(other.Function('x','return [x+'+k+',new TypeError(),this];'));
        }
        other.sharedDispatch = dispatch;
        other.runLocal = other.Function('f','return sharedDispatch(f,7);');
        for(var round=0;round<160;round++) for(var k=0;k<16;k++) {
            var r = dispatch(local[k],7);
            if(r[0]!==7+k || !(r[1] instanceof TypeError) || r[2]!==globalThis)throw 'local realm';
            r = dispatch(foreign[k],7);
            if(r[0]!==7+k || !(r[1] instanceof other.TypeError) || r[1] instanceof TypeError || r[2]!==other)
                throw 'foreign realm';
            r = other.runLocal(local[k]);
            if(!(r[1] instanceof TypeError) || r[2]!==globalThis)throw 'restored realm';
        }
        'ok'
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(run_in(&mut engine, source), "ok", "{tier:?}");
    }
}

#[test]
fn computed_method_reads_preserve_receivers_mutation_and_abrupt_order() {
    let source = r#"
        function invoke(o,k,x){return o[k](x);}
        function first(x){'use strict';return [this, x+1];}
        function second(x){'use strict';return [this, x+2];}
        var proto={method:first}, object=Object.create(proto), key='method';
        for(var n=0;n<450;n++) {
            var r=invoke(object,key,n);
            if(r[0]!==object || r[1]!==n+1)throw 'warm receiver';
        }
        proto.method=second;
        if(invoke(object,key,3)[1]!==5)throw 'live value';
        object.method=first;
        if(invoke(object,key,3)[1]!==4)throw 'own shadow';
        delete object.method;
        Object.setPrototypeOf(object,{method:first});
        if(invoke(object,key,3)[1]!==4)throw 'same-shape prototype replacement';
        var deep=object;
        for(var depth=0;depth<5;depth++) {
            deep=Object.create(deep);
            for(var n=0;n<50;n++)if(invoke(deep,key,3)[0]!==deep)throw 'deep receiver';
        }
        var getterCalls=0, nested={different:second};
        Object.defineProperty(object,key,{configurable:true,get:function(){
            getterCalls++; invoke(nested,'different',1); return second;
        }});
        for(var n=0;n<450;n++)if(invoke(object,key,3)[1]!==5)throw 'reentrant getter value';
        if(getterCalls!==450)throw 'getter replay';
        Object.defineProperty(object,key,{configurable:true,value:first});
        if(invoke(object,key,3)[1]!==4)throw 'descriptor restored';

        var primitiveKey='computed_test_method';
        String.prototype[primitiveKey]=first;
        Number.prototype[primitiveKey]=first;
        Boolean.prototype[primitiveKey]=first;
        for(var n=0;n<450;n++) {
            for(var v of ['hello',12,true])if(invoke(v,primitiveKey,1)[0]!==v)throw 'boxed receiver';
        }
        String.prototype[primitiveKey]=second;
        if(invoke('hello',primitiveKey,1)[1]!==3)throw 'primitive live value';
        Object.defineProperty(String.prototype,primitiveKey,{configurable:true,get:function(){
            'use strict';if(this!=='hello')throw 'getter primitive receiver';return first;
        }});
        if(invoke('hello',primitiveKey,1)[0]!=='hello')throw 'primitive getter result';
        delete String.prototype[primitiveKey]; delete Number.prototype[primitiveKey];
        delete Boolean.prototype[primitiveKey];
        var symbol=Symbol('method'); object[symbol]=second;
        if(invoke(object,symbol,1)[1]!==3)throw 'symbol method';
        var coercions=0, coercingKey={ [Symbol.toPrimitive]:function(hint){
            if(hint!=='string')throw 'hint';coercions++;return symbol;
        }};
        if(invoke(object,coercingKey,1)[1]!==3 || coercions!==1)throw 'key conversion';
        try{invoke(null,coercingKey,1);throw 'null accepted';}
        catch(e){if(!(e instanceof TypeError) || coercions!==1)throw 'null coercion order';}
        var keyExpressions=0, tagSubstitutions=0;
        function tagKey(){keyExpressions++;return coercingKey;}
        function substitute(){tagSubstitutions++;return 1;}
        function invokeTag(o){return o[tagKey()]`value ${substitute()}`;}
        for(var n=0;n<450;n++) {
            try{invokeTag(n&1?null:undefined);throw 'null tag accepted';}
            catch(e){if(!(e instanceof TypeError))throw e;}
        }
        if(keyExpressions!==450 || coercions!==1 || tagSubstitutions!==0)throw 'tagged null ordering';
        var traps=0, proxy=new Proxy(object,{get:function(target,key,receiver){
            traps++;return Reflect.get(target,key,receiver);
        }});
        if(invoke(proxy,'method',1)[0]!==proxy || traps!==1)throw 'proxy bypass';
        var revoked=Proxy.revocable(object,{}); revoked.revoke();
        try{invoke(revoked.proxy,'method',1);throw 'revoked accepted';}
        catch(e){if(!(e instanceof TypeError))throw e;}
        var args=0, sentinel={};
        function arg(){args++;return 1;}
        function withArg(o,k){return o[k](arg());}
        try{withArg({},'missing');throw 'missing accepted';}
        catch(e){if(!(e instanceof TypeError) || args!==1)throw 'callability order';}
        Object.defineProperty(object,'method',{get:function(){throw sentinel;}});
        try{withArg(object,'method');throw 'getter accepted';}
        catch(e){if(e!==sentinel || args!==1)throw 'getter throw ordering';}
        var table=[first,second];
        for(var n=0;n<450;n++)if(invoke(table,n&1,2)[0]!==table)throw 'numeric method receiver';
        var other=$262.createRealm().global, realmKey='computedRealmMethod';
        String.prototype[realmKey]=function(){return 'local';};
        other.String.prototype[realmKey]=other.Function("return 'foreign';");
        var foreignInvoke=other.Function('s','k','return s[k]();');
        for(var n=0;n<450;n++) {
            if(invoke('x',realmKey,0)!=='local' || foreignInvoke('x',realmKey)!=='foreign')throw 'active realm';
        }
        delete String.prototype[realmKey]; delete other.String.prototype[realmKey];
        'ok'
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        match engine.eval(source, false).expect("parse") {
            Completion::Value(value) => assert_eq!(value, "ok", "{tier:?}"),
            Completion::Throw { name, message } => panic!("{tier:?}: {name}: {message}"),
        }
    }
}

#[test]
fn legacy_function_reflection_diagnostics_preserve_lazy_materialization() {
    let mut engine = Engine::new();
    engine.set_tier(crate::bytecode::Tier::Interp);
    assert_eq!(
        run_in(
            &mut engine,
            r#"
        var conversions=0;
        var key={ [Symbol.toPrimitive]:function(hint){
            if(hint!=='string')throw 'bad hint'; conversions++; return 'arguments';
        }};
        function lazy(x){
            var a=lazy[key];
            if(a[0]!==7 || a.length!==2 || a!==lazy.arguments)throw 'lazy reflection';
        }
        function ready(x){
            if(ready[key]!==arguments)throw 'materialized reflection';
        }
        if(lazy.arguments!==null)throw 'inactive reflection';
        lazy(7,undefined); ready(8);
        if(conversions!==2)throw 'replayed conversion';
        if(lazy.arguments!==null)throw 'retained activation';
        'ok'
    "#
        ),
        "ok"
    );
}

#[test]
fn jit_direct_call_releases_the_last_callee_reference_after_return_and_throw() {
    for mode in [1, 2] {
        let mut engine = Engine::new();
        engine.set_tier(crate::bytecode::Tier::Jit);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(
                &mut engine,
                r#"
            var sentinel = {}, keepContext = 0;
            var victim = function(x) {
                try {
                    if(x) {
                        victim.prototype = null;
                        victim = null;
                        if(x===2) throw sentinel;
                    }
                    return 17;
                } finally {}
            };
            function dispatch(f,x) { var keep = keepContext; return f((f=null,x)) + keep; }
            for(var i=0;i<401;i++) dispatch(victim,0);
            'ok'
        "#
            ),
            "ok"
        );
        // The function's handle lives only in this helper frame (the collector scans the stack).
        let weak = crate::gc_test::in_frame(|| {
            let global = crate::value::Value::Obj(engine.interp.global);
            let value = engine
                .interp
                .eval_in_realm(&global, "victim")
                .unwrap_or_else(|_| panic!("live victim"));
            let ValueView::Obj(function) = (value).view() else {
                panic!("function object")
            };
            crate::value::Gc::downgrade(&function)
        });
        let source = format!("try {{ dispatch(victim,{mode}) }} catch(error) {{ error===sentinel ? 'sentinel' : 'wrong error' }}");
        assert_eq!(
            run_in(&mut engine, &source),
            if mode == 1 { "17" } else { "sentinel" }
        );
        // The body removed both the global owner and the default prototype's constructor
        // backlink. Only the caller operand remained; cleanup must leave no word that retains
        // it, so the next collection finds it dead.
        engine.interp.gc_collect();
        assert_eq!(
            weak.strong_count(),
            0,
            "mode {mode}: last callee must be destroyed"
        );
    }
}

#[test]
fn return_transfers_preserve_values_receiver_context_and_abrupt_completion() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(
                &mut engine,
                r#"
            var token = {}, marker = Symbol('return'), calls = 0, reads = 0;
            var values = [undefined, null, false, -0, NaN, 2n**90n, 'owned string', marker, token];
            function leaf(value) { for (var j=0; j<2; j++) calls++; return value; }
            function bare() { calls++; return; }
            var receiver = {value: token, pass: function(value) {
                var nested = leaf(value);
                if(this.value !== token) throw 'lost receiver';
                return nested;
            }};
            function caught(value) { try { return receiver.pass(value); } catch(e) { throw e; } }
            for(var k=0; k<900; k++) {
                var value = values[k % values.length];
                if(!Object.is(caught(value), value)) throw 'return identity';
                if(bare() !== undefined) throw 'bare return';
            }
            var getter = {get value() { reads++; throw token; }};
            function failed() { return getter.value; }
            try { failed(); throw 'missing abrupt'; } catch(e) { if(e !== token) throw e; }
            function replaced() { try { return token; } finally { return marker; } }
            function overridden() { try { return token; } finally { throw marker; } }
            if(replaced() !== marker) throw 'finally return';
            try { overridden(); throw 'missing finally'; } catch(e) { if(e !== marker) throw e; }
            if(calls !== 2700 || reads !== 1) throw 'replayed effect';
            'ok'
        "#
            ),
            "ok",
            "tier {tier:?}"
        );
    }
}

#[test]
fn megamorphic_direct_call_can_grow_the_secondary_cache_in_a_nested_call() {
    assert_eq!(
        run_jit(
            r#"
        var grow = false, churn = [];
        function nested(f,x){return f(x);}
        function target(x){
            if(grow){
                grow=false;
                for(var k=0;k<1200;k++) {
                    var f=Function('x','return x+'+k+';');
                    churn.push(f); nested(f,1); nested(f,2);
                }
            }
            return x+1;
        }
        var handlers=[target];
        for(var k=1;k<16;k++) handlers.push(Function('x','return x+'+k+';'));
        function dispatch(f,x){return f(x);}
        for(var round=0;round<256;round++) for(var k=0;k<16;k++) dispatch(handlers[k],round);
        grow=true;
        if(dispatch(target,7)!==8 || churn.length!==1200)throw 'nested growth';
        if(dispatch(target,9)!==10 || dispatch(handlers[15],2)!==17)throw 'caller restoration';
        'ok'
    "#
        ),
        "ok"
    );
}

#[test]
fn megamorphic_cache_does_not_keep_discarded_functions_alive() {
    let mut engine = Engine::new();
    engine.set_tier(crate::bytecode::Tier::Jit);
    engine.set_tier_threshold(0);
    assert_eq!(
        run_in(
            &mut engine,
            r#"
        var refs = [];
        function dispatch(f,x){return f(x);}
        (function(){
            var functions = [];
            for(var k=0;k<16;k++) functions.push(Function('x','return x+'+k+';'));
            for(var r=0;r<200;r++) for(var k=0;k<16;k++) dispatch(functions[k],r);
            for(var k=0;k<16;k++) refs.push(new WeakRef(functions[k]));
        })();
        'ok'
    "#
        ),
        "ok"
    );
    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    assert!(
        engine.interp.call_overflow.retained_bytes() > 0,
        "exercise actual secondary fills"
    );
    // A separate job permits weak clearing; the still-live dispatch chunk and engine cache
    // must not root functions or the function/prototype cycles.
    assert_eq!(
        run_in(
            &mut engine,
            "$262.gc(); refs.every(function(ref){return ref.deref()===undefined;})"
        ),
        "true"
    );
    assert_eq!(
        run_in(
            &mut engine,
            r#"
        var sum=0;
        for(var k=0;k<512;k++) sum+=dispatch(Function('x','return x+'+k+';'),1);
        sum
    "#
        ),
        "131328"
    );
}

#[test]
fn native_function_realm_survives_prototype_changes_and_call_cache_warmup() {
    // CreateBuiltinFunction/BuiltinCallOrConstruct use immutable [[Realm]], not [[Prototype]].
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(
                &mut engine,
                r#"
            const foreign = $262.createRealm().global;
            const localParse = JSON.parse, otherParse = foreign.JSON.parse;
            function invoke(fn, text) { return fn(text); }
            function verify(fn, proto, ErrorType) {
                for (let i=0; i<250; i++) {
                    if (Object.getPrototypeOf(invoke(fn, '{}')) !== proto) throw 'wrong result realm';
                }
                try { invoke(fn, '{'); throw 'missing parse error'; }
                catch (e) { if (!(e instanceof ErrorType)) throw 'wrong error realm'; }
            }
            verify(localParse, Object.prototype, SyntaxError);
            Object.setPrototypeOf(localParse, foreign.Function.prototype);
            verify(localParse, Object.prototype, SyntaxError);
            Object.setPrototypeOf(otherParse, Function.prototype);
            verify(otherParse, foreign.Object.prototype, foreign.SyntaxError);
            Object.setPrototypeOf(otherParse, null);
            verify(otherParse, foreign.Object.prototype, foreign.SyntaxError);
            let applied=0;
            const proxy=new Proxy(localParse,{apply(target,receiver,args){applied++;return Reflect.apply(target,receiver,args);}});
            if (invoke(proxy,'{"n":3}').n !== 3 || applied !== 1) throw 'proxy bypass';
            const remoteEval=foreign.eval;
            if (invoke(remoteEval,'Array') !== foreign.Array) throw 'indirect eval realm';
            'ok'
        "#
            ),
            "ok",
            "{tier:?}"
        );
    }
}

#[test]
fn native_function_realm_is_kept_by_the_function_not_by_the_registry() {
    let mut engine = Engine::new();
    run_in(
        &mut engine,
        r#"
        var foreign = $262.createRealm().global;
        var retainedNative = foreign.JSON.parse;
        Object.setPrototypeOf(retainedNative, null);
        foreign = null;
    "#,
    );
    engine.interp.gc_collect();
    assert_eq!(
        engine.interp.realms.len(),
        2,
        "live built-in retains its original realm"
    );
    assert_eq!(
        run_in(
            &mut engine,
            "Object.getPrototypeOf(retainedNative('{}')) !== Object.prototype"
        ),
        "true"
    );
    run_in(&mut engine, "retainedNative = null");
    engine.interp.gc_collect();
    engine.interp.gc_collect();
    assert_eq!(
        engine.interp.realms.len(),
        1,
        "weak metadata cannot keep an unused realm alive"
    );
}

#[test]
fn bound_call_diagnostics_preserve_arguments_returns_and_exceptions() {
    // Also run with TRUST_JS_TRACE_BOUND_CALLS=1. Diagnostic inspection must not
    // trigger these traps/getters or alter BoundFunction [[Call]] forwarding.
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(
                &mut engine,
                r#"
                const marker = {};
                let hooks = 0;
                const payload = new Proxy({}, {
                    get() { hooks++; throw marker; },
                    ownKeys() { hooks++; throw marker; },
                    getOwnPropertyDescriptor() { hooks++; throw marker; }
                });
                function target(first, second) {
                    'use strict';
                    if (this !== marker || first !== payload || second !== 7) throw marker;
                    return payload;
                }
                const bound = target.bind(marker, payload);
                Object.defineProperty(target, 'name', {get() { hooks++; throw marker; }});
                function outer(value) { return bound(value); }
                const nested = outer.bind(null);
                let okay = true;
                for (let i=0; i<200; i++) okay = okay && nested(7) === payload;
                const throws = (function () { throw marker; }).bind(null);
                try { throws(); okay=false; } catch (error) { okay = okay && error === marker; }
                okay && hooks === 0;
            "#
            ),
            "true",
            "{tier:?}"
        );
    }
}

