#[test]
fn regexp_resource_exhaustion_throws_instead_of_becoming_no_match() {
    // RegExpBuiltinExec returns null only for the matcher's failure result. An implementation
    // limit (here a lowered ceiling on the matcher's backtracking state) is an abrupt completion,
    // not permission to silently select the no-match branch.
    let source = r#"
        const re = /(?:a|b)*(?=c)/y;
        try {
            re.test("ab".repeat(20000)) + ":" + re.lastIndex;
        } catch (error) {
            error.name + ":" + re.lastIndex;
        }
    "#;
    crate::regex::set_backtrack_state_limit(1 << 12);
    let limited = Engine::new().eval(source, false);
    crate::regex::set_backtrack_state_limit(crate::regex::MAX_BACKTRACK_STATE);
    assert!(matches!(limited, Ok(Completion::Value(ref value)) if value == "RangeError:0"));
    assert_eq!(run(source), "false:0");
}

#[test]
fn repeated_short_regexp_matches_amortize_but_do_not_starve_host_interruption() {
    // A native RegExp operation is force-polled by dispatch before it starts. Model cancellation
    // arriving immediately afterwards: a Rust loop of individually tiny successful matches must
    // observe it through the shared execution cadence instead of doing an atomic read per match
    // or postponing cancellation until the whole native operation returns.
    let control = std::sync::Arc::new(crate::RuntimeInterrupt::default());
    let mut engine = Engine::new();
    engine.set_interrupt_handle(control.clone());
    assert!(
        engine.interp.interrupt_poll_force().is_ok(),
        "native entry starts uninterrupted"
    );
    control.cancel();

    let mut observed_at = None;
    for invocation in 1..=0x4000 {
        match crate::builtins::regexp_interrupt_tick(&mut engine.interp) {
            Err(crate::regex::MatchError::Interrupted(crate::InterruptReason::Cancelled)) => {
                observed_at = Some(invocation);
                break;
            }
            Ok(()) => {}
            other => panic!("unexpected polling result before cancellation: {other:?}"),
        }
    }
    assert!(
        observed_at.is_some(),
        "amortized short matches must reach an interruption checkpoint"
    );
}

#[test]
fn syntax_error_is_parse_phase() {
    assert!(Engine::new().eval("function (", false).is_err());
    assert!(Engine::new().eval("1 +", false).is_err());
}

#[test]
fn execution_deadlines_abort_without_running_catch_or_finally_on_every_tier() {
    // HTML §8.1.4.5 "Killing scripts": abort empties the execution-context stack without the
    // normal language mechanisms, including `finally`. Keep the declarations outside the try so
    // the same realm can prove neither author handler observed the host control completion.
    let source = r#"
        var caught = 0, finalized = 0;
        function spin() { while (true) {} }
        try { spin(); }
        catch (error) { caught = 1; }
        finally { finalized = 1; }
    "#;

    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let interrupt = engine.interrupt_handle();
        interrupt.set_deadline(Some(
            std::time::Instant::now() + std::time::Duration::from_millis(20),
        ));
        let started = std::time::Instant::now();
        match engine
            .eval_interruptible(source, false)
            .expect("script parses")
        {
            ExecutionOutcome::Interrupted {
                reason: InterruptReason::DeadlineExceeded,
            } => {}
            ExecutionOutcome::Interrupted { reason } => {
                panic!("unexpected interruption on {tier:?}: {reason:?}")
            }
            ExecutionOutcome::Value(value) => {
                panic!("deadline did not interrupt {tier:?}; returned {value}")
            }
            ExecutionOutcome::Throw { name, message } => {
                panic!("deadline became a JavaScript throw on {tier:?}: {name}: {message}")
            }
        }
        assert!(
            started.elapsed() < std::time::Duration::from_secs(2),
            "{tier:?} did not honor the deadline promptly"
        );

        interrupt.set_deadline(None);
        assert_eq!(
            match engine
                .eval("caught + ':' + finalized", false)
                .expect("parse")
            {
                Completion::Value(value) => value,
                Completion::Throw { name, message } => {
                    panic!("realm did not recover after {tier:?} deadline: {name}: {message}")
                }
            },
            "0:0",
            "{tier:?} exposed host interruption to catch/finally"
        );
    }
}

#[test]
fn cancellation_crosses_threads_and_interrupts_jit_code() {
    let mut engine = Engine::new();
    engine.set_tier(crate::bytecode::Tier::Jit);
    engine.set_tier_threshold(0);
    let interrupt = engine.interrupt_handle();
    let canceller = std::thread::spawn({
        let interrupt = interrupt.clone();
        move || {
            std::thread::sleep(std::time::Duration::from_millis(20));
            interrupt.cancel();
        }
    });
    let started = std::time::Instant::now();
    let outcome = engine
        .eval_interruptible("function spin(){while(true){}} spin()", false)
        .expect("script parses");
    canceller.join().expect("canceller thread");
    assert!(matches!(
        outcome,
        ExecutionOutcome::Interrupted {
            reason: InterruptReason::Cancelled
        }
    ));
    assert!(started.elapsed() < std::time::Duration::from_secs(2));
}

/// `armDeadline()`: this engine's execution deadline, 20 ms ahead. A job that arms its own
/// deadline is interrupted while it runs. Armed before the evaluation, the deadline could expire
/// in the script body on a slow machine, and an interrupted body leaves the jobs it queued to the
/// next evaluation's checkpoint, where nothing would stop a spinning job.
fn arm_deadline(
    i: &mut crate::interpreter::Interp,
    _this: crate::value::Value,
    _args: &[crate::value::Value],
) -> Result<crate::value::Value, crate::value::Value> {
    i.runtime_interrupt.set_deadline(Some(
        std::time::Instant::now() + std::time::Duration::from_millis(20),
    ));
    Ok(crate::value::Value::Undefined)
}

fn define_arm_deadline(engine: &mut Engine) {
    let global = engine.interp.global;
    engine
        .interp
        .def_method(&global, "armDeadline", 0, arm_deadline);
}

#[test]
fn interruption_aborts_a_running_microtask_checkpoint() {
    let mut engine = Engine::new();
    engine.set_tier(crate::bytecode::Tier::Jit);
    engine.set_tier_threshold(0);
    let interrupt = engine.interrupt_handle();
    define_arm_deadline(&mut engine);
    let outcome = engine
        .eval_interruptible(
            r#"
            var caught = 0, finalized = 0, later = 0;
            function spin() { armDeadline(); while (true) {} }
            Promise.resolve().then(() => {
                try { spin(); }
                catch (error) { caught = 1; }
                finally { finalized = 1; }
            }).then(() => { later = 1; });
            "#,
            false,
        )
        .expect("script parses");
    assert!(matches!(
        outcome,
        ExecutionOutcome::Interrupted {
            reason: InterruptReason::DeadlineExceeded
        }
    ));
    interrupt.set_deadline(None);
    assert_eq!(
        match engine
            .eval("caught + ':' + finalized + ':' + later", false)
            .expect("parse")
        {
            Completion::Value(value) => value,
            Completion::Throw { name, message } => panic!("threw {name}: {message}"),
        },
        "0:0:0"
    );
}

/// HTML's microtask checkpoint runs until the queue is empty. A long await chain must settle
/// instead of being truncated by an engine-side job budget.
#[test]
fn microtask_checkpoint_drains_long_await_chains_to_completion() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        let completion = engine
            .eval(
                r#"
                var settled = "pending";
                async function chain(n) { var s = 0; for (var i = 0; i < n; i++) s += await i; return s; }
                chain(250000).then(function (s) { settled = s; }, function (e) { settled = "rejected"; });
                "#,
                false,
            )
            .expect("parse");
        assert!(matches!(completion, Completion::Value(_)));
        assert_eq!(
            match engine.eval("String(settled)", false).expect("parse") {
                Completion::Value(value) => value,
                Completion::Throw { name, message } => panic!("threw {name}: {message}"),
            },
            "31249875000",
            "{tier:?}"
        );
    }
}

/// Host interruption (HTML may abort a running script at any time) must reach code that
/// never takes a loop back-edge: exponential recursion makes billions of calls and no loops.
#[test]
fn interruption_stops_loop_free_recursion() {
    for tier in [crate::bytecode::Tier::Bytecode, crate::bytecode::Tier::Jit] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let interrupt = engine.interrupt_handle();
        interrupt.set_deadline(Some(
            std::time::Instant::now() + std::time::Duration::from_millis(100),
        ));
        let started = std::time::Instant::now();
        let outcome = engine
            .eval_interruptible(
                "function f(n) { return n === 0 ? 0 : f(n - 1) + f(n - 1); } f(60);",
                false,
            )
            .expect("script parses");
        assert!(
            matches!(
                outcome,
                ExecutionOutcome::Interrupted {
                    reason: InterruptReason::DeadlineExceeded
                }
            ),
            "{tier:?}"
        );
        assert!(
            started.elapsed() < std::time::Duration::from_secs(20),
            "{tier:?}: {:?}",
            started.elapsed()
        );
    }
}

/// Without a job budget, an endlessly self-re-enqueueing microtask loop must still be
/// stoppable by the host, and the interrupted checkpoint discards the remaining jobs.
#[test]
fn interruption_stops_an_endless_microtask_chain() {
    let mut engine = Engine::new();
    let interrupt = engine.interrupt_handle();
    interrupt.set_deadline(Some(
        std::time::Instant::now() + std::time::Duration::from_millis(50),
    ));
    let started = std::time::Instant::now();
    let outcome = engine
        .eval_interruptible(
            "var turns = 0; (function again() { turns++; Promise.resolve().then(again); })();",
            false,
        )
        .expect("script parses");
    assert!(matches!(
        outcome,
        ExecutionOutcome::Interrupted {
            reason: InterruptReason::DeadlineExceeded
        }
    ));
    assert!(started.elapsed() < std::time::Duration::from_secs(10));
    interrupt.set_deadline(None);
    assert!(engine
        .interp
        .gc_heap
        .agent
        .work
        .borrow()
        .promises
        .is_empty());
    // A collection at every safepoint (GC stress) may leave the 50 ms deadline a single turn.
    let several = if crate::gc_test::stress_active() {
        "true"
    } else {
        "String(turns > 1)"
    };
    match engine.eval(several, false).expect("parse") {
        Completion::Value(value) => assert_eq!(value, "true"),
        Completion::Throw { name, message } => panic!("threw {name}: {message}"),
    }
}

/// Arguments objects that only `arguments.length`/`arguments[key]` can reach are represented by
/// the plain list of actual arguments (ECMA-262 CreateUnmappedArgumentsObject /
/// CreateMappedArgumentsObject remain observably exact): out-of-range and non-index keys,
/// `callee`, @@iterator (the %Array.prototype.values% intrinsic), inherited accessors that
/// receive and mutate the object, escaping/written objects, and sloppy parameter aliasing.
#[test]
fn lazily_represented_arguments_objects_are_observably_exact() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let source = r#"
            var out = [];
            var values = Array.prototype.values;
            function len() { return arguments.length; }
            function sum() { var s = 0; for (var i = 0; i < arguments.length; i++) s += arguments[i]; return s; }
            function babelRest(a) { "use strict"; for (var _len = arguments.length, rest = new Array(_len > 1 ? _len - 1 : 0), _key = 1; _key < _len; _key++) rest[_key - 1] = arguments[_key]; return a + ":" + rest.join(","); }
            function outOfRange() { return arguments[5] === undefined && arguments[-1] === undefined; }
            function negZero() { return arguments[-0]; }
            function strKey() { return arguments["1"]; }
            function sloppyCallee() { return arguments["callee"] === sloppyCallee; }
            function strictCallee() { "use strict"; try { arguments["callee"]; return "no"; } catch (e) { return e instanceof TypeError; } }
            function iter() { return arguments[Symbol.iterator] === values; }
            function toStr() { return typeof arguments["toString"]; }
            function escapes() { return arguments; }
            function writes() { arguments[0] = 9; return arguments[0]; }
            function applies() { return sum.apply(null, arguments); }
            function spreads() { return [...arguments].length; }
            function sl(a, b) { if (arguments.length < 2) b = 10; a = a + 1; return a + b + arguments.length; }
            function slElem(a) { return arguments[0]; }
            function slElemAlias(a) { a = 5; return arguments[0]; }
            function slWriteArg(a) { arguments[0] = 7; return a; }
            Object.defineProperty(Object.prototype, "grab", { get() { this[0] = 42; return this.length; }, configurable: true });
            function strictGrab() { "use strict"; var x = arguments["grab"]; return arguments[0] + ":" + arguments.length + ":" + x; }
            function sloppyNoParamsGrab() { var x = arguments["grab"]; return arguments[0]; }
            var acc = 0;
            for (var i = 0; i < 300; i++) {
              acc += len(1, 2, 3) + sum(1, 2, 3) + negZero(7) + strKey(1, 2) + sl(1) + sl(1, 2)
                + slElem(3) + slElemAlias(1) + slWriteArg(1);
            }
            out.push(acc, babelRest(1, 2, 3), babelRest(1), outOfRange(1, 2), sloppyCallee(),
              strictCallee(), iter(1), toStr());
            out.push(Object.prototype.toString.call(escapes(1)), writes(1), applies(1, 2, 3), spreads(1, 2));
            out.push(strictGrab(1), sloppyNoParamsGrab(1), strictGrab(), sl(1, 2, 3));
            delete Object.prototype.grab;
            out.join("|")
        "#;
        match engine.eval(source, false).expect("parse") {
            Completion::Value(value) => assert_eq!(
                value,
                "15600|1:2,3|1:|true|true|true|true|function|[object Arguments]|9|6|2|42:1:1|42|42:0:0|7",
                "{tier:?}"
            ),
            Completion::Throw { name, message } => panic!("{tier:?} threw {name}: {message}"),
        }
    }
}

/// ECMA-262 FunctionDeclarationInstantiation → IteratorBindingInitialization for destructuring
/// formals: left-to-right binding with defaults, nested/rest patterns, getter order, iterable
/// sources, captured names, holes, a shadowing body `var`, `length`, and TypeError on nullish.
#[test]
fn compiled_destructuring_parameters_bind_in_order() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let source = r#"
            var out = [];
            function a({ x, y }) { return x + y; }
            function b({ x = 1, y } = {}) { return x + ":" + y; }
            function c([p, q], r) { return p + q + r; }
            function d({ m: { n } }) { return n; }
            function e({ x }) { return () => x; }
            function f({ a, ...rest }) { return a + Object.keys(rest).join(""); }
            function g([h, ...t]) { return h + t.length; }
            function k([, second]) { return second; }
            function shadow({ x }) { var x; return x; }
            function order({ a, b }) { return a + b; }
            function len1(a, { b }, c = 1, d) {}
            var log = "";
            var getters = { get a() { log += "a"; return 1; }, get b() { log += "b"; return 2; } };
            var acc = 0;
            for (var i = 0; i < 300; i++) {
              acc += a({ x: 1, y: 2 }) + c([1, 2], 3) + d({ m: { n: 4 } }) + e({ x: 5 })()
                + g([1, 2, 3]) + k([0, 7]) + shadow({ x: 1 });
            }
            out.push(acc, b(), b({ x: 3, y: 4 }), b({ y: 5 }), f({ a: "A", p: 1, q: 2 }),
              c("xy", "z"), c(new Set([1, 2]), 0));
            log = ""; out.push(order(getters), log, len1.length);
            try { a(); out.push("no error"); } catch (err) { out.push(err instanceof TypeError); }
            try { c(null); out.push("no error"); } catch (err) { out.push(err instanceof TypeError); }
            out.join("|")
        "#;
        match engine.eval(source, false).expect("parse") {
            Completion::Value(value) => assert_eq!(
                value, "8700|1:undefined|3:4|1:5|Apq|xyz|3|3|ab|2|true|true",
                "{tier:?}"
            ),
            Completion::Throw { name, message } => panic!("{tier:?} threw {name}: {message}"),
        }
    }
}

/// ECMA-262 FunctionDeclarationInstantiation (step 26, IteratorBindingInitialization) evaluates a
/// parameter's initializer only for an undefined argument, left to right, before the body. A
/// closure in the body captures the initialized binding. Such functions compile; all tiers agree.
#[test]
fn compiled_captured_default_parameters_bind_their_initialized_value() {
    fn compiles(src: &str) -> bool {
        let stmts = crate::parser::parse_script(src, false).ok().expect("parse");
        let func = stmts
            .iter()
            .find_map(|s| match s {
                crate::ast::Stmt::FuncDecl(f) => Some(f.clone()),
                _ => None,
            })
            .expect("a function declaration");
        crate::bytecode::compile(&func).is_some()
    }
    assert!(compiles("function f(a, b = 1) { return () => a + b; }"));
    assert!(compiles(
        "function g(a = 2, b = a * 3) { return () => [a, b]; }"
    ));
    assert!(compiles(
        "function h(x = 10) { const inc = () => ++x; inc(); return x; }"
    ));
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let source = r#"
            var out = [];
            function f(a, b = 1) { return () => a + b; }
            function g(a = 2, b = a * 3) { return () => [a, b].join(","); }
            function h(x = 10) { const inc = () => ++x; inc(); return x; }
            var log = [];
            function k(a = (log.push("a"), 1), b = (log.push("b"), 2)) { return () => a + b; }
            function m(a = 1) { const get = () => a; a = 9; return [arguments.length, arguments[0], get()].join(","); }
            function v(x = 1) { var x; return () => x; }
            function w(x = 1) { var x = 2; return () => x; }
            class T { constructor(data = "", token = undefined) { this.f = () => data + (token === undefined ? "" : token); } }
            var acc = 0;
            for (var i = 0; i < 300; i++) acc += f(i)() + f(i, 2)() + h() + h(i);
            out.push(acc, f(1, undefined)(), f(1, null)(), g()(), g(4)(), g(undefined, 1)());
            out.push(k(undefined, 5)(), log.join(""));
            out.push(m(3), m(), v()(), v(4)(), w()());
            out.push(new T().f(), new T("q").f(), new T("q", "!").f());
            try { (function (a = b, b = 1) { return () => a; })(); out.push("no error"); }
            catch (err) { out.push(err instanceof ReferenceError); }
            out.join("|")
        "#;
        match engine.eval(source, false).expect("parse") {
            Completion::Value(value) => assert_eq!(
                value, "139050|2|1|2,6|4,12|2,1|6|a|1,3,9|0,,9|1|4|2||q|q!|true",
                "{tier:?}"
            ),
            Completion::Throw { name, message } => panic!("{tier:?} threw {name}: {message}"),
        }
    }
}

/// ECMA-262 ContainsExpression: initializers and computed keys nested in a parameter's binding
/// pattern are parameter expressions, evaluated by IteratorBindingInitialization in the function's
/// parameter scope. A compiled outer function must therefore keep the bindings they name in its
/// environment when they are the inner function's only reference (Webflow IX2's
/// `function eT({comparator: a = eI})`); otherwise the call threw a ReferenceError. Per
/// FunctionDeclarationInstantiation step 28 those expressions cannot see the inner body's own
/// declarations, so a body `var`/`let` of the same name still leaves them reading the outer one.
#[test]
fn compiled_outer_bindings_reach_nested_parameter_pattern_expressions() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let source = r#"
            function outer() {
                for (var i = 0; i < 2; i++);
                let same = (a, b) => a === b, fallback = 5, key = "k", tail = 7, nested = "n";
                var shadow = "outer";
                function object({ compare: c = same, value = fallback }) { return [c(1, 1), value]; }
                function array([first = fallback, , third = tail] = []) { return first + third; }
                function computed({ [key]: picked }) { return picked; }
                function deep({ a: { b: [c = nested] = [] } = {} }) { return c; }
                const arrow = ({ x = fallback * 2 }) => x;
                class C { method({ y = tail } = {}) { return y; } }
                function laterVar({ s = shadow }) { var shadow = "inner"; return s; }
                function laterLet(s = shadow) { let shadow = "inner"; return s; }
                function laterClosure(read = () => shadow) { var shadow = "inner"; return read(); }
                return [
                    object({}).join(","), object({ compare: () => 0, value: 1 }).join(","),
                    array(), array([1, 0, 2]), computed({ k: "hit" }), deep({}),
                    arrow({}), new C().method(), laterVar({}), laterLet(), laterClosure()
                ].join("|");
            }
            var shadow = "global";
            outer() + "/" + outer()
        "#;
        let expected = "true,5|0,1|12|3|hit|n|10|7|outer|outer|outer";
        match engine.eval(source, false).expect("parse") {
            Completion::Value(value) => {
                assert_eq!(value, format!("{expected}/{expected}"), "{tier:?}")
            }
            Completion::Throw { name, message } => panic!("{tier:?} threw {name}: {message}"),
        }
    }
}

/// ECMA-262 FunctionDeclarationInstantiation binds a trailing rest parameter to a fresh Array of
/// the remaining arguments, for every entry path: direct and cached calls, apply/spread, native
/// callbacks, constructors, methods and arrows, captured or not, with and without defaults.
#[test]
fn compiled_rest_parameters_collect_surplus_arguments() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let source = r#"
            var out = [];
            function f(...xs) { return xs; }
            function g(a, ...xs) { return a + ":" + xs.join(","); }
            function h(...xs) { return () => xs.length; }
            function k(a = 5, ...r) { return a + r.length; }
            function mutate(...xs) { xs.push(9); return xs.length; }
            var arrow = (...a) => a.length;
            var obj = { m(first, ...rest) { return first + rest.length; } };
            class C { constructor(...parts) { this.n = parts.length; } }
            var acc = 0;
            for (var i = 0; i < 300; i++) {
              acc += f().length + f(1, 2).length + mutate(1) + mutate() + arrow(1, 2, 3)
                + obj.m(1, 2, 3) + new C(1, 2).n + h(1, 2, 3)();
            }
            out.push(acc);
            out.push(Array.isArray(f()), f(1, 2) instanceof Array, f(1, 2) !== f(1, 2),
              JSON.stringify(f(1, "a", null)));
            out.push(g(1), g(1, 2, 3), k(), k(1, 2, 3), f.length, g.length, k.length);
            out.push(f.apply(null, [4, 5, 6]).length, f(...[7, 8]).length,
              [1, 2, 3].map(function (...a) { return a.length; }).join(""));
            out.push(h()(), Object.getPrototypeOf(f(1)) === Array.prototype);
            out.join("|")
        "#;
        match engine.eval(source, false).expect("parse") {
            Completion::Value(value) => assert_eq!(
                value, "4800|true|true|true|[1,\"a\",null]|1:|1:2,3|5|3|0|1|0|3|2|333|0|true",
                "{tier:?}"
            ),
            Completion::Throw { name, message } => panic!("{tier:?} threw {name}: {message}"),
        }
    }
}

/// ECMA-262 GetNewTarget in ordinary functions compiled without an activation: the value is the
/// current call's [[NewTarget]] in every tier, around nested calls and constructs, through
/// Reflect.construct/bound constructors/classes, while an arrow that observes it still sees its
/// enclosing function's value.
#[test]
fn new_target_in_lean_ordinary_functions_follows_each_call() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let source = r#"
            var log = [];
            function F() { return new.target === undefined ? "call" : (new.target === F ? "F" : new.target.name); }
            function G() {}
            function Inner() { return new.target === undefined ? "u" : "c"; }
            function Outer() {
                var before = new.target === Outer;
                var inner = Inner();
                var constructed = new Inner();
                var after = new.target === Outer;
                this.r = [before, inner, constructed instanceof Inner, after].join(",");
            }
            function WithArrow() { var a = () => new.target; this.r = a() === WithArrow; }
            class Base { constructor() { this.t = new.target.name; } }
            class Derived extends Base {}
            for (var i = 0; i < 300; i++) {
                log.length = 0;
                log.push(F());
                log.push(new F() instanceof F);
                log.push(Reflect.construct(F, [], G) instanceof G);
                log.push(F.call(null), F.apply(null, []));
                var B = F.bind(null);
                log.push(new B() instanceof F);
                log.push(new Outer().r);
                log.push(new WithArrow().r);
                log.push(new Base().t, new Derived().t);
            }
            log.join("|")
        "#;
        match engine.eval(source, false).expect("parse") {
            Completion::Value(value) => assert_eq!(
                value, "call|true|true|call|call|true|true,u,true,true|true|Base|Derived",
                "{tier:?}"
            ),
            Completion::Throw { name, message } => panic!("{tier:?} threw {name}: {message}"),
        }
    }
}

/// ECMA-262 Await: the resumption job runs in FIFO order with other reactions, a rejected await
/// throws at the await site, and an awaited thenable is adopted through its `then`.
#[test]
fn await_resumption_order_and_completions_follow_the_specification() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        engine
            .eval(
                r#"
                var log = [];
                async function a() { log.push("a1"); await undefined; log.push("a2"); await null; log.push("a3"); }
                async function b() {
                    try { await Promise.reject(new Error("boom")); } catch (e) { log.push("caught:" + e.message); }
                    var v = await { then(r) { log.push("thenable"); r(7); } };
                    log.push("v" + v);
                    return "done";
                }
                a();
                Promise.resolve().then(function () { log.push("p1"); }).then(function () { log.push("p2"); });
                b().then(function (r) { log.push(r); });
                log.push("sync");
                "#,
                false,
            )
            .expect("parse");
        assert_eq!(
            match engine.eval("log.join(',')", false).expect("parse") {
                Completion::Value(value) => value,
                Completion::Throw { name, message } => panic!("threw {name}: {message}"),
            },
            "a1,sync,a2,p1,caught:boom,a3,p2,thenable,v7,done",
            "{tier:?}"
        );
    }
}

/// Await's reaction steps are unobservable built-ins with no result capability. Suspending on an
/// already-settled value allocates only the PromiseResolve wrapper, not reaction functions or a
/// dependent promise.
#[test]
fn await_allocates_no_reaction_functions_or_result_promise() {
    let mut engine = Engine::new();
    engine
        .eval(
            "async function spin(n) { for (var i = 0; i < n; i++) await i; } spin(64);",
            false,
        )
        .expect("parse");
    let before = crate::value::heap_allocated_objects(&engine.interp.gc_heap);
    engine.eval("spin(4000);", false).expect("parse");
    let per_await =
        (crate::value::heap_allocated_objects(&engine.interp.gc_heap) - before) as f64 / 4000.0;
    assert!(per_await < 1.5, "{per_await} objects allocated per await");
}

/// Promise.prototype.then whose SpeciesConstructor is provably %Promise% skips the generic
/// NewPromiseCapability (an executor, resolving functions and a capability record): only the
/// result promise is allocated. Every author-visible step of the generic path (an own or
/// inherited accessor `constructor`, a replaced or deleted @@species, a subclass) still runs.
#[test]
fn promise_then_with_the_intrinsic_species_allocates_only_its_result() {
    let mut engine = Engine::new();
    run_in(
        &mut engine,
        "var pending = new Promise(function () {}); function f() {} pending.then(f);",
    );
    let before = crate::value::heap_allocated_objects(&engine.interp.gc_heap);
    run_in(
        &mut engine,
        "for (var i = 0; i < 4000; i++) pending.then(f);",
    );
    let per_then =
        (crate::value::heap_allocated_objects(&engine.interp.gc_heap) - before) as f64 / 4000.0;
    assert!(per_then < 1.5, "{per_then} objects allocated per then");

    // Expected values are node's.
    let source = r#"
        var log = [];
        function note(s) { log.push(s); }
        var P = Promise, PP = Promise.prototype;
        var species = Object.getOwnPropertyDescriptor(P, Symbol.species);
        var r = P.resolve(1).then(function (v) { note('a' + v); return v + 1; });
        note(Object.getPrototypeOf(r) === PP);
        r.then(function (v) { note('b' + v); });
        var p1 = P.resolve(2);
        Object.defineProperty(p1, 'constructor', { get() { note('own'); return P; } });
        p1.then(function (v) { note('c' + v); });
        class Sub extends P {}
        PP.constructor = Sub;
        note(P.resolve(3).then(function (v) { note('d' + v); }) instanceof Sub);
        PP.constructor = P;
        Object.defineProperty(PP, 'constructor', {
            get() { note('proto'); return P; }, configurable: true });
        P.resolve(4).then(function () {});
        Object.defineProperty(PP, 'constructor', {
            value: P, writable: true, enumerable: false, configurable: true });
        Object.defineProperty(P, Symbol.species, {
            get() { note('species'); return undefined; }, configurable: true });
        note(Object.getPrototypeOf(P.resolve(5).then(function (v) { note('e' + v); })) === PP);
        delete P[Symbol.species];
        Object.defineProperty(Function.prototype, Symbol.species, {
            get() { note('inherited'); return Sub; }, configurable: true });
        note(P.resolve(6).then(function () {}) instanceof Sub);
        delete Function.prototype[Symbol.species];
        Object.defineProperty(P, Symbol.species, species);
        var p5 = P.resolve(7);
        Object.setPrototypeOf(p5, Sub.prototype);
        note(p5.then(function (v) { note('f' + v); }) instanceof Sub);
        note(Sub.resolve(8).then(function (v) { note('g' + v); }) instanceof Sub);
        P.reject(9).then(null, function (e) { note('h' + e); return 'x'; })
            .then(function (v) { note('i' + v); });
        P.resolve(10).then(function () { return { then(res) { note('thenable'); res(11); } }; })
            .then(function (v) { note('j' + v); });
        log.join()
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(&mut engine, source),
            "true,own,true,proto,species,true,inherited,true,true,true",
            "{tier:?}"
        );
        assert_eq!(
            run_in(&mut engine, "log.join()"),
            "true,own,true,proto,species,true,inherited,true,true,true,\
             a1,c2,d3,e5,f7,g8,h9,b2,ix,thenable,j11",
            "{tier:?}"
        );
    }
}

/// Well-known Symbols are the Agent's (ECMA-262 §6.1.5.1) and %Promise%/%AggregateError% are
/// intrinsics: replacing or watching the global `Symbol`, `Promise`, `AggregateError` and `Intl`
/// bindings changes neither ToPrimitive, Object.prototype.toString, the iterator protocol, a
/// later Realm's or module namespace's symbols, nor Promise.prototype.then/finally/Promise.any.
#[test]
fn engine_reaches_well_known_symbols_and_intrinsics_without_global_bindings() {
    let source = r#"
        var out = [];
        var S = Symbol, iter = Symbol.iterator, tag = Symbol.toStringTag;
        class Tagged { get [Symbol.toStringTag]() { return 'Tagged'; } }
        var prim = { [Symbol.toPrimitive](hint) { return hint === 'number' ? 42 : hint; } };
        var P = Promise, AE = AggregateError, settled = "", hits = 0;
        function note() { for (var i = 0; i < arguments.length; i++) settled += arguments[i] + ","; }
        globalThis.Symbol = function () { throw new Error('global Symbol read'); };
        Object.defineProperty(globalThis, 'Promise', {
            get() { hits++; return P; }, configurable: true });
        globalThis.AggregateError = function () { throw new Error('global AggregateError read'); };
        globalThis.Intl = undefined;
        out.push(prim + 1, `${prim}`, +prim);
        out.push([new Map, P.resolve(), new Tagged, new Set, function* () {}()]
            .map(function (o) { return Object.prototype.toString.call(o); }).join());
        out.push([...new Set([1, 2])].join(), Array.from(new Map([[3, 4]])).join());
        var [a, b] = 'xy';
        out.push(a + b, (1234.5).toLocaleString('en-US'));
        var other = $262.createRealm().global;
        out.push(other.Symbol.iterator === iter, other.Symbol.toStringTag === tag);
        P.resolve(1).then(function (v) { note('then' + v); });
        P.resolve(2).finally(function () { note('finally'); });
        P.reject(3).catch(function (v) { note('catch' + v); });
        Object.defineProperty(Array.prototype, '0', {
            set(v) { throw new Error('errors used Set'); }, configurable: true });
        // "A newly created AggregateError object" has no own `message` (V8 adds one).
        P.any([P.reject(4), P.reject(5)]).catch(function (e) {
            note(e instanceof AE, e.constructor === AE, Object.hasOwn(e, 'message'),
                e.errors.join('+'), Object.getOwnPropertyDescriptor(e, 'errors').enumerable);
        });
        P.any([]).catch(function (e) { note(e instanceof AE, e.errors.length); });
        out.join()
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(&mut engine, source),
            "default1,string,42,[object Map],[object Promise],[object Tagged],[object Set],\
             [object Generator],1,2,3,4,xy,1,234.5,true,true",
            "{tier:?}"
        );
        assert_eq!(
            run_in(
                &mut engine,
                "delete Array.prototype[0]; settled + ';' + hits"
            ),
            "then1,finally,catch3,true,0,true,true,false,4+5,false,;0",
            "{tier:?}"
        );
    }
    // A module namespace created after `Symbol` is replaced still gets its @@toStringTag.
    let mut engine = Engine::new();
    run_in(&mut engine, "globalThis.Symbol = undefined;");
    engine
        .eval_module(
            "import * as ns from '/dep.js'; globalThis.nsTag = Object.prototype.toString.call(ns);",
            "/main.js",
            |spec, _| (spec == "/dep.js").then(|| (spec.to_string(), "export var x;".to_string())),
        )
        .unwrap();
    assert_eq!(run_in(&mut engine, "nsTag"), "[object Module]");
}

/// The live-object ceiling is an engine setting: retention below it succeeds, retention above it
/// still throws a catchable RangeError after a full collection, and the default never falls
/// below the former fixed ceiling.
#[test]
fn live_object_limit_is_configurable_and_enforced() {
    assert!(Engine::new().live_object_limit() >= crate::interpreter::MIN_LIVE_OBJECT_LIMIT as u64);
    let retain = |limit: u64, count: u32| {
        let mut engine = Engine::new();
        engine.set_live_object_limit(limit);
        let source = format!(
            "var kept = [], outcome = 'ok'; try {{ for (var i = 0; i < {count}; i++) kept.push({{ i: i }}); }} \
             catch (e) {{ outcome = e instanceof RangeError ? 'range:' + e.message : 'other'; }} kept = null; outcome"
        );
        match engine.eval(&source, false).expect("parse") {
            Completion::Value(value) => value,
            Completion::Throw { name, message } => panic!("threw {name}: {message}"),
        }
    };
    assert_eq!(retain(150_000, 140_000), "ok");
    assert_eq!(retain(150_000, 250_000), "range:allocation limit exceeded");
}

/// The handler that catches the live-object RangeError must be able to allocate while the
/// retained graph is still reachable: the throwing safepoint re-arms the next collection
/// instead of leaving it due, which made the first allocation in `catch` collect and throw again.
#[test]
fn live_object_limit_error_handler_can_allocate() {
    use crate::bytecode::Tier;
    for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        engine.set_live_object_limit(150_000);
        let source = "var kept = [], outcome = 'ok';
            function fill() { for (var i = 0; i < 250000; i++) kept.push({ i: i }); }
            try { fill(); } catch (e) {
                var notes = [];
                for (var j = 0; j < 2000; j++) notes.push({ j: j, name: e.name });
                outcome = e.name + ':' + e.message + ':' + notes.length + ':' + notes[1999].j;
            }
            kept = null; outcome";
        match engine.eval(source, false).expect("parse") {
            Completion::Value(value) => assert_eq!(
                value, "RangeError:allocation limit exceeded:2000:1999",
                "{tier:?}"
            ),
            Completion::Throw { name, message } => panic!("{tier:?} threw {name}: {message}"),
        }
    }
}

/// Allocation makes a collection due through the heap's budgets alone: the live-object count,
/// which also collected once it grew by 100,000 objects (or an eighth) until P1 S6 step 9a,
/// only enforces the live-object limit. With this heap's nursery budget and byte budget floor
/// out of reach, 300,000 objects, half of them kept, are allocated without a collection at every
/// tier; with the engine's nursery budget back, which they have long spent, the next safepoint
/// collects (minorly: the byte budget's floor stays out of reach, so that no major collection
/// follows).
#[test]
fn object_count_alone_does_not_collect() {
    use crate::bytecode::Tier;
    // GC stress collects at every safepoint after an allocation.
    if crate::gc_test::stress_active() {
        return;
    }
    for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        // The end-of-eval task boundary would collect after this much growth: defer it, as the
        // embed API's `defer_task_garbage_collection` does.
        engine.interp.gc_heap.agent.task_deferred.set(true);
        let heap = engine.interp.gc_heap.clone();
        // This heap's nursery budget, which TRUST_JS_GC_NURSERY_BYTES sets for every heap in the
        // process (`gc_collect::configure_heap`).
        let set_nursery = |bytes: usize| heap.core.borrow_mut().set_nursery_bytes(Some(bytes));
        let collections = || heap.core.borrow().collections();
        let live = || crate::value::heap_live_objects(&heap);
        // The byte budget's floor, which TRUST_JS_GC_MIN_HEAP_BYTES sets, at the engine's growth.
        heap.core.borrow_mut().set_heap_growth(1 << 40, 100);
        set_nursery(1 << 40);
        let before = collections();
        let allocated = crate::value::heap_allocated_objects(&heap);
        let source = "var kept = [];
            function fill(n) { for (var i = 0; i < n; i++) { kept.push({ i: i }); var dead = { i: i }; } }
            fill(150000); kept.length";
        assert_eq!(run_in(&mut engine, source), "150000", "{tier:?}");
        assert_eq!(collections(), before, "{tier:?}: no collection was due");
        assert!(
            crate::value::heap_allocated_objects(&heap) - allocated >= 300_000,
            "{tier:?}"
        );
        // Unswept, the dead count as live.
        let unswept = live();
        assert!(unswept >= 300_000, "{tier:?}: {unswept} live objects");
        // The engine's nursery budget, 2 MiB, which those objects' cells have spent.
        set_nursery(2 << 20);
        assert!(heap.core.borrow().collection_due(), "{tier:?}");
        // The next safepoint, this loop's at the latest, collects.
        assert_eq!(
            run_in(&mut engine, "for (var j = 0; j < 2; j++); j"),
            "2",
            "{tier:?}"
        );
        assert_eq!(collections(), before + 1, "{tier:?}");
        assert!(
            live() <= unswept - 100_000,
            "{tier:?}: {} live objects",
            live()
        );
    }
}

/// Deeply nested source either runs or is a catchable SyntaxError, on every tier and on a 1 MiB
/// thread stack: the parser bounds the nesting of statements, expressions and patterns
/// (`MAX_PARSE_DEPTH`), and the parser, the AST passes, the compiler and the tree-walking
/// evaluator continue on fresh stack segments when theirs runs low. Before, a few thousand
/// nested blocks or `else if`s overflowed the native stack and aborted. Values are node's
/// (given `--stack-size` large enough to parse them).
#[test]
fn deeply_nested_source_runs_or_throws_syntax_error() {
    // (description, JavaScript building the source for `n` levels, expected completion)
    let cases: &[(&str, &str, &str)] = &[
        ("new chain", "'new '.repeat(n) + 'G === G'", "true"),
        ("exponents", "Array(n).fill('1').join('**')", "1"),
        ("assignments", "'x = '.repeat(n) + '3'", "3"),
        ("conditionals", "'1 ? '.repeat(n) + '5' + ' : 0'.repeat(n)", "5"),
        ("blocks", "'{'.repeat(n) + 'x = 1;' + '}'.repeat(n)", "1"),
        (
            "else if",
            "'if (x === -1) 0; ' + 'else if (x === -1) 0; '.repeat(n) + 'else 7;'",
            "7",
        ),
        ("labels", "Array.from({ length: n }, (_, k) => 'l' + k + ': ').join('') + '8;'", "8"),
        ("parentheses", "'('.repeat(n / 2) + '1' + ')'.repeat(n / 2)", "1"),
        ("arrays", "'['.repeat(n / 2) + ']'.repeat(n / 2) + '.length'", "1"),
        ("arrows", "'typeof ' + '(() => '.repeat(n / 4) + '1' + ')'.repeat(n / 4)", "function"),
        (
            "patterns",
            "'var ' + '['.repeat(n / 2) + 'y' + ']'.repeat(n / 2) + ' = ' + '['.repeat(n / 2) + '5' + ']'.repeat(n / 2) + '; y'",
            "5",
        ),
        (
            "functions",
            "'(function () { return '.repeat(n / 8) + '9' + '; })()'.repeat(n / 8)",
            "9",
        ),
        ("templates", "'`${'.repeat(n / 4) + '4' + '}`'.repeat(n / 4)", "4"),
    ];
    let mut script = String::from(
        "var a = {}; a.b = a; function g() { return g; } function G() { return G; } var x = 0;
         function run(build, n) {
             var source = build(n);
             try { return String((0, eval)(source)); } catch (e) { return e.name; }
         }
         var results = [];",
    );
    for (_, build, _) in cases {
        script.push_str(&format!(
            "results.push(run(function (n) {{ return {build}; }}, 4000));
             results.push(run(function (n) {{ return {build}; }}, 12000));"
        ));
    }
    script.push_str("results.join('|')");
    let expected = cases
        .iter()
        .map(|(_, _, value)| format!("{value}|SyntaxError"))
        .collect::<Vec<_>>()
        .join("|");
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let script = script.clone();
        let expected = expected.clone();
        let outcome = std::thread::Builder::new()
            .name(format!("deep-source-{tier:?}"))
            .stack_size(1 << 20)
            .spawn(move || {
                let mut engine = Engine::new();
                engine.set_tier(tier);
                engine.set_tier_threshold(0);
                assert_eq!(run_in(&mut engine, &script), expected, "{tier:?}");
            })
            .expect("spawn")
            .join();
        assert!(outcome.is_ok(), "{tier:?} failed");
    }
}

/// Left-nested chains are as deep as they are long, but generated and obfuscated code builds
/// them with hundreds of thousands of links (node runs a million `+` operands), so they are not
/// bounded by the nesting limit: these 30,000-link chains, six times that limit, run on every
/// tier on a 1 MiB thread stack, at the top level and in a function that compiles. Operator,
/// property and call chains are compiled and evaluated in a loop; the other walks grow their
/// stack. Values are node's where node has the stack for them (it runs out on long property,
/// call and tagged-template chains).
#[test]
fn long_expression_chains_run() {
    // (description, JavaScript building an expression of `n` links, expected value)
    let cases: &[(&str, &str, &str)] = &[
        ("additions", "Array(n).fill('1').join('+')", "30000"),
        (
            "concatenation",
            "'(' + Array(n).fill(\"'x'\").join('+') + ').length'",
            "30000",
        ),
        (
            "logical",
            "Array(n).fill('one').join(' && ') + ' || 2'",
            "1",
        ),
        (
            "coalescing",
            "Array(n).fill('none').join(' ?? ') + ' ?? 3'",
            "3",
        ),
        ("bitwise", "Array(n).fill('one').join(' | ')", "1"),
        ("comma", "'(' + Array(n).fill('one').join(', ') + ')'", "1"),
        ("template", "'`' + '${one}'.repeat(n) + '`.length'", "30000"),
        ("member chain", "'a' + '.b'.repeat(n) + ' === a'", "true"),
        (
            "index chain",
            "'a' + '[\"b\"]'.repeat(n) + ' === a'",
            "true",
        ),
        ("optional chain", "'a' + '?.b'.repeat(n) + ' === a'", "true"),
        ("call chain", "'g' + '()'.repeat(n) + ' === g'", "true"),
        ("method chain", "'a' + '.m()'.repeat(n) + ' === a'", "true"),
        (
            "tagged templates",
            "'g' + '`x`'.repeat(n) + ' === g'",
            "true",
        ),
    ];
    let mut script = String::from(
        "var one = 1, none = null, a = { m() { return a; } }; a.b = a;
         function g() { return g; }
         var results = [];",
    );
    for (_, build, _) in cases {
        script.push_str(&format!(
            "results.push(String((0, eval)((function (n) {{ return {build}; }})(30000))));
             var inner = Function('return ' + (function (n) {{ return {build}; }})(30000));
             results.push(String(inner()) + ':' + String(inner()));"
        ));
    }
    script.push_str("results.join('|')");
    let expected = cases
        .iter()
        .map(|(_, _, value)| format!("{value}|{value}:{value}"))
        .collect::<Vec<_>>()
        .join("|");
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let script = script.clone();
        let expected = expected.clone();
        let outcome = std::thread::Builder::new()
            .name(format!("long-chains-{tier:?}"))
            .stack_size(1 << 20)
            .spawn(move || {
                let mut engine = Engine::new();
                engine.set_tier(tier);
                engine.set_tier_threshold(0);
                assert_eq!(run_in(&mut engine, &script), expected, "{tier:?}");
            })
            .expect("spawn")
            .join();
        assert!(outcome.is_ok(), "{tier:?} failed");
    }
}

/// JSON.parse, its reviver walk, JSON.stringify and `flat(Infinity)` recurse once per level of
/// nesting and now continue on fresh native stack segments (a release build parses the million
/// levels node does); all of them aborted the process with a native stack overflow at a few tens
/// of thousands of levels. Debug frames are larger, so this runs 10,000 levels.
#[test]
fn deeply_nested_json_and_flat_complete() {
    let outcome = std::thread::Builder::new()
        .name("deep-json".to_string())
        .stack_size(1 << 20)
        .spawn(|| {
            let mut engine = Engine::new();
            run_in(
                &mut engine,
                "function depth(v) { var d = 0; while (Array.isArray(v)) { v = v[0]; d++; } return d; }
                 var n = 10000;
                 var text = '['.repeat(n) + '1' + ']'.repeat(n);
                 var nested = [1]; for (var k = 1; k < n; k++) nested = [nested];
                 var objects = '{\"a\":'.repeat(n) + '1' + '}'.repeat(n);
                 [
                     depth(JSON.parse(text)),
                     depth(JSON.parse(text, function (key, value) { return value; })),
                     JSON.parse(objects) !== null,
                     JSON.stringify(nested).length,
                     nested.flat(Infinity).length
                 ].join(':')",
            )
        })
        .expect("spawn")
        .join()
        .expect("deep JSON panicked");
    assert_eq!(outcome, "10000:10000:true:20001:1");
}

/// A discarded ArrayBuffer keeps its data until the collector finds it, and a buffer is a single
/// object, so buffer data drives collection too: allocating 96 MiB of typed arrays that are
/// never kept must not retain them all (a 16 MiB-per-iteration loop used to reach 16 GB).
#[test]
fn discarded_array_buffer_data_triggers_collection() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(
                &mut engine,
                "var total = 0;
                 for (var k = 0; k < 96; k++) total += new Uint8Array(1024 * 1024).length;
                 total"
            ),
            "100663296"
        );
        let retained: usize = engine
            .interp
            .array_buffers
            .values()
            .map(|data| data.byte_len().unwrap_or(0))
            .sum();
        assert!(
            retained <= 72 * 1024 * 1024,
            "{tier:?} retains {retained} bytes of discarded buffers"
        );
    }
}

/// Releasing the last reference to a long object chain must not recurse once per link. Each case
/// runs on a deliberately small native stack, where per-link recursion overflowed at a few
/// thousand links; the chains here are two orders of magnitude longer.
#[test]
fn releasing_long_object_chains_uses_bounded_native_stack() {
    let cases: &[(&str, &str)] = &[
        (
            "linked list",
            "var h = null; for (var i = 0; i < 200000; i++) h = { next: h, v: i }; h = null;",
        ),
        (
            "closure chain",
            "var f = null; for (var i = 0; i < 100000; i++) f = (function (g) { return function () { return g; }; })(f); f = null;",
        ),
        (
            "nested arrays",
            "var a = []; for (var i = 0; i < 200000; i++) a = [a]; a = null;",
        ),
        (
            "bound argument chain",
            "var b = null; function f(x) { return x; } for (var i = 0; i < 100000; i++) b = f.bind(null, b); b = null;",
        ),
        (
            "bound target chain",
            "function C() { this.k = 1; } var b = C; for (var i = 0; i < 3000; i++) b = b.bind(null); if (new b().k !== 1) throw new Error('bound construct'); b = null;",
        ),
        (
            "prototype chain",
            "var p = {}; for (var i = 0; i < 100000; i++) p = Object.create(p); p = null;",
        ),
        (
            "collected cycle",
            "var c = { self: null }; c.self = c; for (var i = 0; i < 200000; i++) c = { next: c }; c = null;",
        ),
    ];
    for &(name, source) in cases {
        let source = source.to_owned();
        let outcome = std::thread::Builder::new()
            .name(format!("drop-{name}"))
            .stack_size(1 << 20)
            .spawn(move || {
                let mut engine = Engine::new();
                let completion = engine.eval(&source, false).expect("parse");
                if let Completion::Throw {
                    name: error,
                    message,
                } = completion
                {
                    panic!("{name}: threw {error}: {message}");
                }
                engine.interp.gc_collect();
                // The engine is still usable afterwards.
                match engine.eval("String(1 + 1)", false).expect("parse") {
                    Completion::Value(value) => assert_eq!(value, "2"),
                    Completion::Throw { name, message } => panic!("threw {name}: {message}"),
                }
            })
            .expect("spawn")
            .join();
        assert!(outcome.is_ok(), "{name} panicked");
    }
}

#[test]
fn interruption_escapes_native_nested_evaluation_without_becoming_a_throw() {
    let mut engine = Engine::new();
    let interrupt = engine.interrupt_handle();
    interrupt.set_deadline(Some(
        std::time::Instant::now() + std::time::Duration::from_millis(20),
    ));
    let outcome = engine
        .eval_interruptible(
            r#"
            var caught = 0, finalized = 0;
            try { $262.evalScript("while (true) {}"); }
            catch (error) { caught = 1; }
            finally { finalized = 1; }
            "#,
            false,
        )
        .expect("script parses");
    assert!(matches!(
        outcome,
        ExecutionOutcome::Interrupted {
            reason: InterruptReason::DeadlineExceeded
        }
    ));
    interrupt.set_deadline(None);
    assert_eq!(
        match engine
            .eval("caught + ':' + finalized", false)
            .expect("parse")
        {
            Completion::Value(value) => value,
            Completion::Throw { name, message } => panic!("threw {name}: {message}"),
        },
        "0:0"
    );
}

#[test]
fn user_navigation_interrupt_is_rearmable_at_a_task_boundary() {
    let mut engine = Engine::new();
    let interrupt = engine.interrupt_handle();
    interrupt.request_user_navigation();
    assert!(matches!(
        engine.eval_interruptible("1", false).expect("parse"),
        ExecutionOutcome::Interrupted {
            reason: InterruptReason::UserNavigation
        }
    ));
    interrupt.begin_user_interaction();
    assert_eq!(
        match engine.eval("2", false).expect("parse") {
            Completion::Value(value) => value,
            Completion::Throw { name, message } => panic!("threw {name}: {message}"),
        },
        "2"
    );
}

#[test]
fn equality_and_coercion() {
    assert_eq!(run("1 == '1'"), "true");
    assert_eq!(run("1 === '1'"), "false");
    assert_eq!(run("null == undefined"), "true");
    assert_eq!(run("NaN === NaN"), "false");
    assert_eq!(run("typeof 1"), "number");
    assert_eq!(run("typeof 'x'"), "string");
    assert_eq!(run("typeof undefinedGlobalThing"), "undefined");
}

#[test]
fn classes_basic() {
    assert_eq!(run("class C {} typeof C"), "function");
    assert_eq!(run("class C { m(){ return 42; } } new C().m()"), "42");
    assert_eq!(
        run("class C { constructor(x){ this.x = x; } } new C(7).x"),
        "7"
    );
    assert_eq!(run("class C {} C.name"), "C");
    assert_eq!(run("class C { static s(){ return 9; } } C.s()"), "9");
    assert_eq!(
        run("class C { #p = 5; get(){ return this.#p; } } new C().get()"),
        "5"
    );
    assert_eq!(run("class C { f = 3; } new C().f"), "3");
}

#[test]
fn class_static_initializers_can_construct_complete_instances() {
    // ECMA-262 ClassDefinitionEvaluation installs [[Fields]] and [[PrivateMethods]]
    // before evaluating static elements (local snapshot e28783d5fc9d).
    let source = r#"
        function check(ok, message) { if (!ok) throw new Error(message); }
        function exercise() {
            const trace = [];
            const key = Symbol('field');
            class Codec {
                static singleton = new Codec;
                absent;
                values = (trace.push('field'), []);
                [key] = 7;
                #value = this.#method();
                #method() { return 11; }
                get #accessor() { return this.#value; }
                constructor() {
                    trace.push('constructor');
                    this.values.push(this.#accessor);
                }
                static { this.second = new this; trace.push('block'); }
            }
            check(Codec.singleton.values.join() === '11', 'self construction');
            check(Codec.second.values.join() === '11', 'static block construction');
            check(Codec.singleton.values !== Codec.second.values, 'fresh fields');
            check(Codec.singleton[key] === 7, 'computed field');
            check(Object.hasOwn(Codec.singleton, 'absent'), 'uninitialized field');
            check(trace.join() === 'field,constructor,field,constructor,block', 'element order');
            class Base { base = 3; }
            class Derived extends Base {
                static singleton = new this;
                own = this.base + 4;
                #method() { return this.own; }
                read() { return this.#method(); }
            }
            check(Derived.singleton.read() === 7, 'default derived constructor');
            class Explicit extends Base {
                static singleton = new this;
                own = 9;
                constructor() { super(); check(this.own === 9, 'derived super fields'); }
            }
            check(Explicit.singleton.base === 3, 'base fields');
            class Default { static singleton = new this; value = 5; }
            check(Default.singleton.value === 5, 'default base constructor');
            let escaped, later = false;
            const sentinel = {};
            try {
                class Throwing {
                    static { escaped = this; new this; }
                    value = (() => { throw sentinel; })();
                    static later = (later = true);
                }
                check(false, 'initializer must throw');
            } catch (error) { check(error === sentinel, 'original abrupt completion'); }
            check(!later, 'later static elements skipped');
            try { new escaped; check(false, 'escaped constructor retains fields'); }
            catch (error) { check(error === sentinel, 'escaped fields'); }
        }
        for (let warm = 0; warm < 5; ++warm) exercise();
        'ok'
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(run_in(&mut engine, source), "ok", "{tier:?}");
    }
}

#[test]
fn classes_inheritance() {
    let src = "class A { constructor(x){ this.x = x; } hello(){ return 'a' + this.x; } } \
               class B extends A { constructor(x){ super(x); this.y = x*2; } hello(){ return super.hello() + this.y; } } \
               const b = new B(3); b.hello() + ',' + b.y";
    assert_eq!(run(src), "a36,6");
    assert_eq!(
        run("class A {} class B extends A {} new B() instanceof A"),
        "true"
    );
    assert_eq!(
        run("class A { m(){return 1;} } class B extends A {} new B().m()"),
        "1"
    );
}

#[test]
fn default_constructor_forwards_args_without_iterator_protocol() {
    // ECMA-262 ClassDefinitionEvaluation: the default constructor's super spread behaves like
    // `constructor(...args) { super(...args); }` EXCEPT that it does not observably call
    // %Symbol.iterator% on %Array.prototype%; the raw argument list is forwarded (see
    // language/statements/class/subclass/default-constructor-spread-override.js).
    let source = r#"
        Array.prototype[Symbol.iterator] = function() { throw new Error('iterator invoked'); };
        class Base { constructor(value, extra) { this.value = value; this.extra = extra; } }
        class Derived extends Base {}
        const instance = new Derived(5, 7);
        String(instance.value) + ':' + String(instance.extra)
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        match engine.eval(source, false).expect("parse") {
            Completion::Value(v) => assert_eq!(v, "5:7", "{tier:?}"),
            Completion::Throw { name, message } => {
                panic!("{tier:?} unexpectedly ran the iterator protocol: {name}: {message}")
            }
        }
    }
}

#[test]
fn written_constructor_spread_still_uses_iterator_protocol() {
    // A user-written `constructor(...args) { super(...args); }` DOES perform argument
    // evaluation; only the default constructor skips the observable %Symbol.iterator% call.
    let source = r#"
        Array.prototype[Symbol.iterator] = function() { throw new TypeError('iterator invoked'); };
        class Base { constructor(value) { this.value = value; } }
        class Derived extends Base { constructor(...args) { super(...args); } }
        new Derived(5);
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        match engine.eval(source, false).expect("parse") {
            Completion::Value(v) => panic!("{tier:?} skipped argument evaluation: {v}"),
            Completion::Throw { name, message } => {
                assert_eq!(name, "TypeError", "{tier:?}");
                assert!(message.contains("iterator invoked"), "{tier:?}: {message}");
            }
        }
    }
}

#[test]
fn nested_default_constructors_restore_super_forwarding() {
    // A default constructor inside another default constructor's field initializer must not
    // leak or steal the outer frame's forwarded argument list.
    let source = r#"
        class Base { constructor() { this.ok = true; } }
        class D2 extends Base {}
        class D1 extends Base { x = new D2(); }
        let d = new D1();
        d.ok && d.x.ok
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        match engine.eval(source, false).expect("parse") {
            Completion::Value(v) => assert_eq!(v, "true", "{tier:?}"),
            Completion::Throw { name, message } => {
                panic!("{tier:?} threw {name}: {message}")
            }
        }
    }
}

/// ECMA-262 §10.2.2 [[Construct]] allocates only for a base constructor, and the default
/// derived constructor (ClassDefinitionEvaluation step 14.a) is a built-in closure. Expected
/// values come from Node 24.
/// ECMA-262 §10.5: a trapless Proxy forwards to its target, and [[SetPrototypeOf]]'s cycle
/// check stops at Proxies, so a Proxy can be its own target's prototype. Reads, writes and `in`
/// then recurse without bound; like V8 (Node 24), throw a catchable RangeError instead of
/// exhausting the native stack. Own-property queries do not walk the chain.
#[test]
fn proxy_prototype_cycles_throw_range_error_instead_of_overflowing() {
    let source = r#"
        const t = {}; const p = new Proxy(t, {}); Object.setPrototypeOf(t, p);
        const r = [];
        for (const [n, f] of [['get', () => p.x], ['set', () => { p.x = 1; }], ['has', () => 'x' in p],
            ['getOwn', () => Object.getOwnPropertyDescriptor(p, 'x')], ['keys', () => Object.keys(p)]]) {
            try { const v = f(); r.push(n + ':ok:' + v); } catch (e) { r.push(n + ':' + e.constructor.name); }
        }
        r.push('after:' + (1 + 1));
        // Nested trapless forwards are bounded well beyond any chain a page can use.
        const chain = n => { let o = {x: 7}; for (let i = 0; i < n; i++) o = new Proxy(o, {}); return o; };
        r.push('chain:' + chain(3000).x);
        try { chain(20000).x; r.push('long:ok'); } catch (e) { r.push('long:' + e.constructor.name); }
        r.join(' ')
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        match engine.eval(source, false).expect("parse") {
            Completion::Value(v) => assert_eq!(
                v,
                "get:RangeError set:RangeError has:RangeError getOwn:ok:undefined keys:ok: after:2 \
                 chain:7 long:RangeError",
                "{tier:?}"
            ),
            Completion::Throw { name, message } => panic!("{tier:?}: {name}: {message}"),
        }
    }
}

#[test]
fn derived_construction_follows_base_allocation_and_default_constructor_steps() {
    let source = r#"
        const log = [];
        class A { constructor(...a) { log.push('A:' + a.join() + ':' + (new.target && new.target.name)); this.a = 1; } }
        class B extends A { b = (log.push('B field:' + this.a), 2); }
        class C extends B { c = (log.push('C field:' + this.b), 3); }
        const c = new C(1, 2);
        log.push([c.a, c.b, c.c, Object.getPrototypeOf(c) === C.prototype].join());
        // OrdinaryCreateFromConstructor reads new.target's prototype once, at the base.
        let reads = 0;
        function NT() {}
        const NTp = { marker: 1 };
        const P = new Proxy(NT, { get(t, k, r) { if (k === 'prototype') { reads++; return NTp; } return Reflect.get(t, k, r); } });
        const viaNT = Reflect.construct(C, [], P);
        log.push('reads=' + reads + ' proto=' + (Object.getPrototypeOf(viaNT) === NTp));
        class E2 extends A { constructor() { super(); } }
        reads = 0; Reflect.construct(E2, [], P); log.push('explicit reads=' + reads);
        // GetSuperConstructor reads the constructor's current [[Prototype]].
        class X { constructor() { this.x = 'X'; } }
        class D extends A {}
        Object.setPrototypeOf(D, X);
        log.push('D:' + new D().x + ':' + ('a' in new D()));
        Object.setPrototypeOf(D, {});
        try { new D(); } catch (e) { log.push('D bad parent:' + e.constructor.name); }
        Object.setPrototypeOf(D, null);
        try { new D(); } catch (e) { log.push('D null parent:' + e.constructor.name); }
        try { C(); } catch (e) { log.push('call:' + e.constructor.name); }
        class E extends A { constructor(r) { if (r === 1) return { o: 1 }; if (r === 2) return 5; if (r === 3) return; super(); } }
        log.push('E1:' + JSON.stringify(new E(1)));
        for (const r of [2, 3]) { try { new E(r); } catch (e) { log.push('E' + r + ':' + e.constructor.name); } }
        class MyArr extends Array {} const m = new MyArr(3); log.push('MyArr:' + m.length + ':' + Array.isArray(m) + ':' + (m instanceof MyArr));
        class MyErr extends Error {} const me = new MyErr('m'); log.push('MyErr:' + me.message + ':' + (me instanceof MyErr) + ':' + me.name);
        class MyMap extends Map {} const mm = new MyMap([[1, 2]]); log.push('MyMap:' + mm.get(1));
        function F(v) { this.v = v; } const BF = F.bind(null, 7); BF.prototype = F.prototype;
        class G extends BF {} log.push('G:' + new G().v + ':' + (new G() instanceof G));
        class H extends A { #p = 9; get p() { return this.#p; } static has(o) { return #p in o; } }
        const h = new H(); log.push('H:' + h.p + ':' + H.has(h) + ':' + H.has(new A()));
        log.join('|')
    "#;
    let expected = "A:1,2:C|B field:1|C field:2|1,2,3,true|A::NT|B field:1|C field:2|\
        reads=1 proto=true|A::NT|explicit reads=1|D:X:false|D bad parent:TypeError|\
        D null parent:TypeError|call:TypeError|E1:{\"o\":1}|E2:TypeError|E3:ReferenceError|\
        MyArr:3:true:true|MyErr:m:true:Error|MyMap:2|G:7:true|A::H|A::A|H:9:true:false";
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        match engine.eval(source, false).expect("parse") {
            Completion::Value(v) => assert_eq!(v, expected, "{tier:?}"),
            Completion::Throw { name, message } => panic!("{tier:?}: {name}: {message}"),
        }
    }
}

/// The native default derived constructor keeps its frame in captured stacks.
#[test]
fn default_derived_constructor_frames_remain_in_error_stacks() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        let source = "class S1 { constructor() { this.s = new Error('x').stack; } } \
            class S2 extends S1 {} class S3 extends S2 { constructor() { super(); } } \
            JSON.stringify([new S3().s, new S2().s])";
        match engine.eval(source, false).expect("parse") {
            Completion::Value(v) => assert_eq!(
                v,
                concat!(
                    r#"["Error: x\n    at new S1 (<anonymous>:1:37)\n    at new S2 (<anonymous>:1:63)"#,
                    r#"\n    at new S3 (<anonymous>:1:124)\n    at <anonymous>:1:153","#,
                    r#""Error: x\n    at new S1 (<anonymous>:1:37)\n    at new S2 (<anonymous>:1:63)"#,
                    r#"\n    at <anonymous>:1:165"]"#
                ),
                "{tier:?}"
            ),
            Completion::Throw { name, message } => panic!("{tier:?}: {name}: {message}"),
        }
    }
}

#[test]
fn instanceof_default_intrinsic_and_override() {
    assert_eq!(
        run(
            "function A(){} function B(){} B.prototype=Object.create(A.prototype); var b=new B(); [b instanceof B,b instanceof A,b instanceof Array].join(',')"
        ),
        "true,true,false"
    );
    assert_eq!(
        run(
            "var calls=0; var rhs={[Symbol.hasInstance](v){calls++;return v===7}}; [(7 instanceof rhs),(8 instanceof rhs),calls].join(',')"
        ),
        "true,false,2"
    );
    assert_eq!(
        run(
            "function C(){} var calls=0; var p=new Proxy({}, {getPrototypeOf(){calls++;return C.prototype}}); [(p instanceof C),calls].join(',')"
        ),
        "true,1"
    );
    // Warm the JIT cache, then mutate facts that shapes do and do not encode. Replacing the
    // prototype value preserves A's shape and must still be observed; adding @@hasInstance
    // changes it and must deopt to the user hook.
    assert_eq!(
        run_jit(
            "function A(){} var o=new A();
             function hit(v, C){ return v instanceof C; }
             for(var i=0;i<1000;i++) hit(o,A);
             var before=hit(o,A);
             A.prototype={};
             var after=hit(o,A), calls=0;
             Object.defineProperty(A, Symbol.hasInstance,
               {value:function(v){calls++;return v===o;}, configurable:true});
             [before,after,hit(o,A),calls].join(',')"
        ),
        "true,false,true,1"
    );
}

#[test]
fn jit_constructor_creation_cache_deopts_on_prototype_changes() {
    assert_eq!(
        run_jit(
            "function C(v){ this.x=v; this.y={v:v}; }
             var last;
             for(var i=0;i<1000;i++) last=new C(i);
             var order=Object.keys(last).join(',');
             var hits=0, p={set x(v){hits+=v;}};
             C.prototype=p;
             var changed=new C(7);
             [last.x,last.y.v,order,hits,Object.hasOwn(changed,'x'),changed.y.v].join(':')"
        ),
        "999:999:x,y:7:false:7"
    );
    assert_eq!(
        run_jit(
            "function C(v){this.x=v;}
             for(var i=0;i<1000;i++) new C(i);
             var hits=0;
             Object.defineProperty(C.prototype,'x',{set:function(v){hits+=v;},configurable:true});
             var o=new C(9);
             hits+':'+Object.hasOwn(o,'x')"
        ),
        "9:false"
    );
    // An inherited writable data property still makes OrdinarySet create an own property. This
    // shape is common in prototype-style constructors; changing it to a setter must invalidate
    // the creation proof before the next store.
    assert_eq!(
        run_jit(
            "function C(v){this.x=v;}
             C.prototype.x=0;
             var last;
             for(var i=0;i<1000;i++) last=new C(i);
             var hits=0;
             Object.defineProperty(C.prototype,'x',
               {set:function(v){hits+=v;},configurable:true});
             var changed=new C(9);
             last.x+':'+Object.hasOwn(last,'x')+':'+hits+':'+Object.hasOwn(changed,'x')"
        ),
        "999:true:9:false"
    );
    // Activation-requiring forwarding constructors learn the initialized size dynamically. Their
    // reserved storage must not weaken the same live prototype/descriptor guards.
    assert_eq!(
        run_jit(
            "function C(){
               this.ctor=(arguments.callee===C);
               this.argc=arguments.length;
               this.initialize.apply(this,arguments);
             }
             C.prototype.x=0;
             C.prototype.initialize=function(v){this.x=v;this.y=v+1;};
             var last;
             for(var i=0;i<1000;i++) last=new C(i);
             var hits=0;
             Object.defineProperty(C.prototype,'x',
               {set:function(v){hits+=v;},configurable:true});
             var changed=new C(9);
             [last.ctor,last.argc,last.x,last.y,Object.hasOwn(last,'x'),hits,
              changed.ctor,changed.argc,Object.hasOwn(changed,'x'),changed.y].join(':')"
        ),
        "true:1:999:1000:true:9:true:1:false:10"
    );
    // The activation-aware construct entry must still honor an explicit object return.
    assert_eq!(
        run_jit(
            "function R(){arguments;return {argc:arguments.length};}
             var r;
             for(var i=0;i<1000;i++) r=new R(1,2,3);
             (r instanceof R)+':'+r.argc"
        ),
        "false:3"
    );
    // One base initializer can run against several subclass prototypes. Creation feedback is
    // polymorphic in prototype identity even when every fresh receiver has the same empty shape;
    // mutating one prototype must invalidate all ways before the next assignment.
    assert_eq!(
        run_jit(
            "function Base(v){this.x=v;}
             function A(v){Base.call(this,v)} function B(v){Base.call(this,v)}
             function C(v){Base.call(this,v)} function D(v){Base.call(this,v)}
             A.prototype=Object.create(Base.prototype);
             B.prototype=Object.create(Base.prototype);
             C.prototype=Object.create(Base.prototype);
             D.prototype=Object.create(Base.prototype);
             var cs=[A,B,C,D], last=[];
             for(var i=0;i<1200;i++){var k=i&3;last[k]=new cs[k](i);}
             var seen=0;
             Object.defineProperty(B.prototype,'x',{
               configurable:true,set:function(v){seen+=v;}
             });
             var changed=new B(7), normal=new C(8);
             [last[0].x,last[1].x,last[2].x,last[3].x,seen,
              Object.hasOwn(changed,'x'),normal.x].join(':')"
        ),
        "1196:1197:1198:1199:7:false:8"
    );
}

#[test]
fn class_methods_non_enumerable() {
    assert_eq!(run("class C { m(){} } Object.keys(new C()).length"), "0");
    assert_eq!(run("class C { get x(){ return 8; } } new C().x"), "8");
}

#[test]
fn destructuring() {
    assert_eq!(run("const [a, b] = [1, 2]; a + b"), "3");
    assert_eq!(run("const [a, , c] = [1, 2, 3]; a + c"), "4");
    assert_eq!(run("const [a, ...rest] = [1, 2, 3]; rest.length"), "2");
    assert_eq!(run("const [a = 9] = []; a"), "9");
    assert_eq!(run("const { x, y } = { x: 1, y: 2 }; x + y"), "3");
    assert_eq!(run("const { a: p, b: q = 5 } = { a: 1 }; p + q"), "6");
    assert_eq!(
        run("const { a, ...rest } = { a: 1, b: 2, c: 3 }; Object.keys(rest).length"),
        "2"
    );
    assert_eq!(
        run("function f({ a, b }) { return a + b; } f({ a: 4, b: 5 })"),
        "9"
    );
    assert_eq!(run("const [[a], { b }] = [[7], { b: 8 }]; a + b"), "15");
    assert_eq!(
        run("let s = 0; for (const [k, v] of [[1, 2], [3, 4]]) s += k + v; s"),
        "10"
    );
}

#[test]
fn memory_caps_convert_blowups_to_rangeerror() {
    // Each of these would otherwise allocate unbounded memory; they must throw instead of OOM.
    assert_eq!(throws("new Array(4294967296)"), "RangeError"); // invalid uint32 length
    assert_eq!(throws("[].length = 4294967296"), "RangeError");
    assert_eq!(throws("'x'.repeat(1e9)"), "RangeError");
    assert_eq!(throws("Array(2 ** 30).join(',')"), "RangeError"); // huge length op
    assert_eq!(throws("[...Array(2 ** 30)]"), "RangeError"); // huge spread
    assert_eq!(throws("Math.max(...Array(2 ** 21))"), "RangeError"); // huge argument list
    assert_eq!(throws("Math.max.apply(null, Array(2 ** 21))"), "RangeError");
    assert_eq!(
        throws("Reflect.apply(Math.max, null, { length: 2 ** 32 })"),
        "RangeError"
    );
    assert_eq!(
        throws("Object.keys(new Proxy({}, { ownKeys: () => ({ length: 2 ** 32 }) }))"),
        "RangeError"
    );
    assert_eq!(throws("(123).toFixed(1e9)"), "RangeError");
    assert_eq!(throws("let s='x'; for(;;){ s += s; }"), "RangeError"); // doubling string
                                                                       // Truncating a huge sparse length must not loop over the whole range (would hang).
    assert_eq!(
        run("var a=[1,2,3]; a.length = 1e9; a.length = 1; a.length"),
        "1"
    );
}

/// Arrays just past the former 2^20-element engine cap (a few million rows of real data) work
/// like in other engines; only absurd lengths throw (see above). Spreading is compiled per tier;
/// the built-ins are tier-independent, so they run once (a million elements is slow in debug).
#[test]
fn million_element_array_operations_succeed() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(
                &mut engine,
                "(function (a) { return [...a].length; })(new Array(1048577).fill(7))"
            ),
            "1048577",
            "{tier:?}"
        );
    }
    let source = "var n = 1048577, a = new Array(n).fill(1);
        a[n - 1] = 7;
        var sparse = []; sparse[n - 1] = 1; sparse[0] = 2;
        [
            a.join('').length,
            'x,'.repeat(n).split(',').length,
            ('abc,def\\n'.repeat(n) + 'z').split('\\n').length,
            a.toReversed()[0],
            a.with(0, 9)[0],
            Float64Array.from(a).length,
            sparse.sort()[1],
            Array.prototype.at.call({ length: 2 ** 53 - 1 }, -1)
        ].join(':')";
    assert_eq!(run(source), "1048577:1048578:1048578:7:9:1048577:2:");
}

