#[test]
fn template_literals() {
    assert_eq!(run("`hello`"), "hello");
    assert_eq!(run("let x = 5; `x is ${x}`"), "x is 5");
    assert_eq!(run("let a=2,b=3; `${a}+${b}=${a+b}`"), "2+3=5");
    assert_eq!(run("`${1}${2}${3}`"), "123");
    assert_eq!(
        run("let o={n:'q'}; `name: ${o.n}, up: ${o.n.toUpperCase()}`"),
        "name: q, up: Q"
    );
    assert_eq!(run("`nested ${`a${1}b`} end`"), "nested a1b end");
    assert_eq!(
        run("`${[1, 2].map(x => `a${`b${x}`}c`).join('|')}`"),
        "ab1c|ab2c"
    );
    assert_eq!(run("`${[1,2,3].map(x=>x*2).join(',')}`"), "2,4,6");
}

#[test]
fn eval_direct_and_indirect() {
    assert_eq!(run("eval('1 + 2 * 3')"), "7");
    assert_eq!(run("eval('var q = 41; q + 1')"), "42");
    assert_eq!(run("var x = 10; eval('x + 5')"), "15"); // direct: sees caller scope
    assert_eq!(
        run("function f(){ var local = 7; return eval('local * 2'); } f()"),
        "14"
    );
    assert_eq!(run("eval(42)"), "42"); // non-string returns unchanged
    assert_eq!(run("var e = eval; e('100')"), "100"); // indirect
    assert_eq!(throws("eval('var = =')"), "SyntaxError");
}

#[test]
fn symbols() {
    assert_eq!(run("typeof Symbol()"), "symbol");
    assert_eq!(run("typeof Symbol.iterator"), "symbol");
    assert_eq!(run("Symbol('x') === Symbol('x')"), "false"); // unique
    assert_eq!(run("var s = Symbol('d'); s.description"), "d");
    assert_eq!(run("var s = Symbol(); var o = {}; o[s] = 7; o[s]"), "7");
    assert_eq!(
        run("var s = Symbol(); var o = {[s]:1, a:2}; Object.keys(o).join(',')"),
        "a"
    ); // symbol skipped
    assert_eq!(
        run("var s = Symbol(); var o = {[s]:1}; Object.getOwnPropertySymbols(o).length"),
        "1"
    );
    assert_eq!(run("Symbol.for('k') === Symbol.for('k')"), "true"); // registry
    assert_eq!(run("String(Symbol('hi'))"), "Symbol(hi)");
    assert_eq!(run("Symbol('z').toString()"), "Symbol(z)");
    assert_eq!(run("Symbol().toString()"), "Symbol()");
    assert_eq!(throws("Symbol() + ''"), "TypeError"); // no implicit string coercion
    assert_eq!(throws("+Symbol()"), "TypeError"); // no number coercion
}

#[test]
fn symbol_registry_is_agent_owned_and_shared_by_realms() {
    let mut first = Engine::new();
    first
        .eval("Symbol.for('agent-key')", false)
        .expect("first registry insertion parses");
    let first_symbol = first.interp.symbol_agent.borrow().global_by_key["agent-key"];

    // Constructing another Engine on the same driver thread must neither clear nor share the
    // first Agent's registry.
    let mut second = Engine::new();
    second
        .eval("Symbol.for('agent-key')", false)
        .expect("second registry insertion parses");
    let second_symbol = second.interp.symbol_agent.borrow().global_by_key["agent-key"];
    assert!(!crate::value::symbol_ptr_eq(&first_symbol, &second_symbol));
    first
        .eval("Symbol.for('agent-key')", false)
        .expect("first registry remains usable");
    assert!(crate::value::symbol_ptr_eq(
        &first_symbol,
        &first.interp.symbol_agent.borrow().global_by_key["agent-key"]
    ));

    // A ShadowRealm is a Realm of the same Agent: both registered and well-known Symbols have
    // the same identity on either side of a wrapped callable boundary.
    assert!(matches!(
        first
            .eval(
                "var sr = new ShadowRealm();
                 [sr.evaluate(\"() => Symbol.for('shadow-key')\")() === Symbol.for('shadow-key'),
                  sr.evaluate(\"() => Symbol.iterator\")() === Symbol.iterator].join(',')",
                false,
            )
            .expect("ShadowRealm symbol checks parse"),
        Completion::Value(ref value) if value == "true,true"
    ));
}

#[test]
fn nested_calls_keep_the_surrounding_agent_activation_on_the_fast_path() {
    // ECMA-262 §9.6: while one Agent's executing thread is performing algorithmic steps, that
    // Agent remains the surrounding Agent. Nested execution contexts therefore must not reinstall
    // the same heap and Symbol Agent on every ordinary call.
    let mut first = Engine::new();
    let mut second = Engine::new();
    let before = crate::value::active_agent_slow_switches();
    assert!(matches!(
        first
            .eval(
                "function nested(n){ return n ? nested(n-1) + 1 : 0 } nested(256)",
                false,
            )
            .expect("first Agent recursion parses"),
        Completion::Value(ref value) if value == "256"
    ));
    let after_first = crate::value::active_agent_slow_switches();
    assert_eq!(
        after_first - before,
        1,
        "one real switch into the first Agent"
    );

    assert!(matches!(
        second
            .eval(
                "function nested(n){ return n ? nested(n-1) + 1 : 0 } nested(256)",
                false,
            )
            .expect("second Agent recursion parses"),
        Completion::Value(ref value) if value == "256"
    ));
    assert_eq!(
        crate::value::active_agent_slow_switches() - after_first,
        1,
        "one real switch into the second Agent"
    );
}

#[cfg(feature = "embed")]
#[test]
fn host_call_entry_activates_the_receiving_engine_agent() {
    fn make_object<'s>(
        ctx: &mut Ctx<'s>,
        _this: Value<'s>,
        _args: &[Value<'s>],
    ) -> Result<Value<'s>, Value<'s>> {
        Ok(Value::Obj(ctx.new_object()))
    }

    /// Call `makeAgentObject` in a scope of `engine`: the object, as an engine handle.
    fn call_make_object(engine: &mut Engine) -> crate::value::Gc {
        engine.scope(|cx| {
            let function = value_in(cx, "makeAgentObject");
            match (cx
                .call_function(&function, Value::Undefined, &[])
                .unwrap_or_else(|_| panic!("host call succeeds")))
            .kind()
            {
                ValueKind::Obj(object) => object.gc(),
                _ => panic!("host call returned an object"),
            }
        })
    }

    // A driver may alternate independent Engines on one native thread. ECMA-262 §9.6 makes the
    // receiving Engine's Agent surrounding before its host task calls into ECMAScript; ordinary
    // nested calls then remain on that Agent without repeating the transition.
    let mut first = Engine::new();
    first.define_global("makeAgentObject", 0, make_object);
    let mut second = Engine::new();
    second.define_global("makeAgentObject", 0, make_object);

    let first_object = call_make_object(&mut first);
    let second_object = call_make_object(&mut second);

    let first_snapshot = crate::value::heap_gc_snapshot(&first.interp.gc_heap);
    let second_snapshot = crate::value::heap_gc_snapshot(&second.interp.gc_heap);
    assert!(first_snapshot
        .iter()
        .any(|object| crate::value::Gc::ptr_eq(object, &first_object)));
    assert!(!second_snapshot
        .iter()
        .any(|object| crate::value::Gc::ptr_eq(object, &first_object)));
    assert!(second_snapshot
        .iter()
        .any(|object| crate::value::Gc::ptr_eq(object, &second_object)));
    assert!(!first_snapshot
        .iter()
        .any(|object| crate::value::Gc::ptr_eq(object, &second_object)));
}

#[test]
fn shadow_realm_heap_transitions_restore_the_caller_heap() {
    let mut engine = Engine::new();
    let _ = engine
        .eval(
            "globalThis.savedShadow = new ShadowRealm();
             savedShadow.evaluate('globalThis.childMarker = {}; 0');
             globalThis.parentMarker = {};",
            false,
        )
        .expect("ShadowRealm ownership probe parses");

    let shadow = match (engine
        .interp
        .global
        .borrow()
        .props
        .get("savedShadow")
        .map(|property| property.value()))
    .map(|__value| (__value).view())
    {
        Some(ValueView::Obj(object)) => object,
        _ => panic!("ShadowRealm object was retained"),
    };
    let parent_object = match (engine
        .interp
        .global
        .borrow()
        .props
        .get("parentMarker")
        .map(|property| property.value()))
    .map(|__value| (__value).view())
    {
        Some(ValueView::Obj(object)) => object,
        _ => panic!("parent marker was retained"),
    };
    let shadow_key = crate::value::Gc::as_ptr(&shadow) as usize;
    let child_id = engine
        .interp
        .shadow_realms
        .get(&shadow_key)
        .unwrap_or_else(|| panic!("ShadowRealm implementation remains available"))
        .id();
    let child_object = engine.interp.with_realm_view(child_id, |child| {
        assert!(std::rc::Rc::ptr_eq(&engine.interp.gc_heap, &child.gc_heap));
        match child
            .global
            .borrow()
            .props
            .get("childMarker")
            .map(|property| property.value().view())
        {
            Some(ValueView::Obj(object)) => object,
            _ => panic!("child marker was retained"),
        }
    });
    let snapshot = crate::value::heap_gc_snapshot(&engine.interp.gc_heap);
    for marker in [&parent_object, &child_object] {
        assert!(snapshot
            .iter()
            .any(|object| crate::value::Gc::ptr_eq(object, marker)));
    }
    assert!(std::rc::Rc::ptr_eq(
        &crate::value::active_gc_heap(),
        &engine.interp.gc_heap
    ));
}

/// The completion value of `source`, or a panic naming what it threw.
fn eval_to_string(engine: &mut Engine, source: &str) -> String {
    match engine.eval(source, false).expect("parses") {
        Completion::Value(value) => value,
        Completion::Throw { name, message } => panic!("threw {name}: {message}"),
    }
}

/// P1 S4: a wrapped function keeps its ShadowRealm alive. The ShadowRealm object can die
/// first; the wrapped function still calls into the realm it came from.
#[test]
fn shadow_realm_wrapped_function_outlives_its_shadow_realm_object() {
    let mut engine = Engine::new();
    assert_eq!(
        eval_to_string(
            &mut engine,
            "var twice = (() => new ShadowRealm().evaluate('(x) => x * 2'))();
             $262.gc(); $262.gc();
             twice(21)",
        ),
        "42"
    );
}

/// P1 S4: a ShadowRealm whose object is otherwise unreachable stays alive while its code runs,
/// across a collection caused by a host callback it calls.
#[test]
fn shadow_realm_survives_a_collection_while_it_runs() {
    let mut engine = Engine::new();
    assert_eq!(
        eval_to_string(
            &mut engine,
            "(() => new ShadowRealm().evaluate(
               '(collect) => { const kept = [1, 2, 3]; collect(); return kept.map(x => x * 2).join() }'
             ))()(() => { $262.gc(); $262.gc(); })",
        ),
        "2,4,6"
    );
}

/// P1 S4: a ShadowRealm stays in the collection's tree while a wrapped function's `name` and
/// `length` are read from it, whatever its getters do. Here the getter queues jobs, reachable
/// only from the realm's own job queue, then collects.
#[test]
fn shadow_realm_stays_traced_while_its_function_is_wrapped() {
    let mut engine = Engine::new();
    assert_eq!(
        eval_to_string(
            &mut engine,
            "var realm = new ShadowRealm();
             var make = realm.evaluate(`(collect) => {
               globalThis.seen = 0;
               const queue = (n) => {
                 const token = { mark: n };
                 Promise.resolve().then(() => { globalThis.seen += token.mark; });
               };
               const read = () => globalThis.seen;
               Object.defineProperty(read, 'name', { get() {
                 for (let i = 1; i <= 20; i++) queue(i);
                 collect();
                 return 'read';
               } });
               return read;
             }`);
             var read = make(() => {
               $262.gc(); $262.gc();
               for (let i = 0; i < 1000; i++) ({ filler: [i] });
             });
             realm.evaluate('0');
             read() + ':' + read.name",
        ),
        // One Agent job queue: returning from the ShadowRealm runs no nested checkpoint.
        "0:read"
    );
    // The queued tokens survived both collections and ran at the script's checkpoint.
    assert_eq!(eval_to_string(&mut engine, "read()"), "210");
}

/// P1 S4: parsed code can serve several engines on one thread, one after another. A
/// closure's `name` is a string of its own engine's heap, never one an AST-level template cached
/// from the heap that first ran the code (here already dropped).
#[test]
fn function_name_templates_serve_only_their_heap() {
    let body = crate::parser::parse_script(
        "var f = function () {}; var g = () => 0; function h() {}",
        false,
    )
    .ok()
    .expect("source");
    let name_words = |engine: &mut Engine| -> Vec<u64> {
        assert!(engine.interp.run_program(&body).is_ok(), "program runs");
        ["f", "g", "h"]
            .iter()
            .map(|binding| {
                let global = crate::value::Value::Obj(engine.interp.global);
                let Ok(function) = engine.interp.member_get(&global, binding) else {
                    panic!("binding {binding}");
                };
                match (engine.interp.member_get(&function, "name")).map(|__value| (__value).view())
                {
                    Ok(ValueView::Str(name)) => name.cell_word(),
                    _ => panic!("{binding}.name is a string"),
                }
            })
            .collect()
    };
    let mut first = Engine::new();
    name_words(&mut first);
    drop(first);
    let mut second = Engine::new();
    for word in name_words(&mut second) {
        assert!(
            second.interp.gc_heap.core.borrow().is_allocated_word(word),
            "a closure's name is a string of its own heap"
        );
    }
}

/// P1 S4 review: an AST-level template's name strings stay roots only while the
/// parsed code holding the template lives. Discarded code leaves nothing rooted in the heap.
#[test]
fn discarded_function_templates_release_their_name_strings() {
    const NAME_BYTES: usize = 64 * 1024;
    let mut engine = Engine::new();
    // The collection that finds discarded code dead still traces its templates (they die in
    // its sweep, with the closures holding the code), so their strings go in the next one.
    let live_bytes = |engine: &mut Engine| {
        engine.interp.gc_collect();
        engine.interp.gc_collect();
        engine.interp.gc_heap.core.borrow().stats().live_bytes
    };
    eval_to_string(&mut engine, "(function warm() {}); 0");
    let before = live_bytes(&mut engine);
    for i in 0..16 {
        let name = format!("f{i}{}", "a".repeat(NAME_BYTES));
        eval_to_string(&mut engine, &format!("(function {name}() {{}}); 0"));
    }
    let after = live_bytes(&mut engine);
    // Retained templates would keep all 16 names (1 MiB); allow a few to stray stack words.
    assert!(
        after < before + 4 * NAME_BYTES,
        "discarded templates kept their names: live bytes {before} -> {after}"
    );
}

/// P1 S5: a property-creation cache (`IC_CREATE`) names its receiver's prototype by
/// address. Once that prototype dies and its pin is pruned, a new object can take the address,
/// and the cache must not stand for the new object's chain: here a setter of the created name.
#[test]
fn creation_caches_do_not_trust_a_reused_prototype_address() {
    // The test needs the dead prototype's address back, so it reruns itself alone in a child
    // process, where no other test thread can take that address first (added when objects came
    // from the process allocator, which the suite's other test threads share).
    const CHILD: &str = "TRUST_JS_TEST_ADDRESS_REUSE_CHILD";
    if std::env::var_os(CHILD).is_none() {
        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::creation_caches_do_not_trust_a_reused_prototype_address",
                "--test-threads=1",
            ])
            .env(CHILD, "1")
            .output()
            .expect("isolated address-reuse test");
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            output.status.success() && stdout.contains("1 passed"),
            "{stdout}\n{}",
            String::from_utf8_lossy(&output.stderr)
        );
        return;
    }
    for tier in [crate::bytecode::Tier::Bytecode, crate::bytecode::Tier::Jit] {
        // A tier's fresh heap can allocate at the previous tier's addresses, its prototype where
        // the previous new object was. Between stack scrubs, no handle the previous tier left in
        // a frame survives to retain it.
        crate::scrubbed(|| creation_cache_after_address_reuse(tier));
    }
}

#[inline(never)]
fn creation_cache_after_address_reuse(tier: crate::bytecode::Tier) {
    let mut engine = Engine::new();
    engine.set_tier(tier);
    engine.set_tier_threshold(0);
    eval_to_string(
        &mut engine,
        "var C = class { constructor() { this.x = 1; } };
         function NT() {}
         var args = [];
         var hits = 0;
         var desc = { set(v) { hits++; }, configurable: true };
         NT.prototype = {};
         for (var i = 0; i < 20; i++) Reflect.construct(C, args, NT);
         0",
    );
    let cached = crate::gc_test::in_frame(|| {
        let global = crate::value::Value::Obj(engine.interp.global);
        let nt = engine.interp.member_get(&global, "NT").ok().expect("NT");
        let proto = engine
            .interp
            .member_get(&nt, "prototype")
            .ok()
            .expect("NT.prototype");
        crate::gc_test::HiddenAddress::of(&proto)
    });
    eval_to_string(&mut engine, "NT.prototype = null; 0");
    // The first collection finds the prototype dead and prunes its pin; the second frees
    // its address (the heap keeps a pinned dead cell reserved until then).
    engine.interp.gc_collect();
    engine.interp.gc_collect();
    let reused = crate::gc_test::in_frame(|| object_at(&mut engine, cached))
        .expect("a new object takes the dead prototype's address");
    let global = crate::value::Value::Obj(engine.interp.global);
    assert!(engine
        .interp
        .member_set(&global, "P2", crate::value::Value::Obj(reused))
        .is_ok());
    assert_eq!(
        eval_to_string(
            &mut engine,
            "Object.defineProperty(P2, 'x', desc);
             NT.prototype = P2;
             var o = Reflect.construct(C, args, NT);
             hits + ':' + Object.hasOwn(o, 'x')",
        ),
        "1:false",
        "{tier:?}: the setter on the new prototype runs"
    );
}

/// A new plain object at `address`, allocating until the allocator hands that address out.
#[inline(never)]
fn object_at(
    engine: &mut Engine,
    address: crate::gc_test::HiddenAddress,
) -> Option<crate::value::Gc> {
    let mut held = Vec::new();
    for _ in 0..200_000 {
        let object = crate::value::Object::new(Some(engine.interp.object_proto));
        if crate::value::Gc::as_ptr(&object) as usize == address.get() {
            return Some(object);
        }
        held.push(object);
    }
    None
}

/// P1 S4: a ShadowRealm's roots count only while its object is marked, so a realm
/// kept only by its own wrapped function, stored inside it, is collected.
#[test]
fn shadow_realm_kept_only_through_itself_is_collected() {
    let mut engine = Engine::new();
    eval_to_string(
        &mut engine,
        "(() => {
           const realm = new ShadowRealm();
           realm.evaluate('(f) => { globalThis.kept = f; }')(realm.evaluate('() => 1'));
         })(); 0",
    );
    assert_eq!(engine.interp.shadow_realms.len(), 1);
    engine.interp.gc_collect();
    assert!(
        engine.interp.shadow_realms.is_empty(),
        "a realm kept only through itself was retained"
    );
}

/// P1 S4 (I5): a collected ShadowRealm ends without resuming its suspended coroutines, here a
/// module body parked at a top-level await (`VmCoro::resume` asserts that no coroutine resumes
/// in the collector's eviction step). A global holds the realm until the parked body is seen:
/// under GC stress a collection inside the evaluation may take an unreachable realm earlier.
#[test]
fn collected_shadow_realm_ends_without_resuming_its_coroutines() {
    let mut engine = Engine::new();
    engine.set_module_loader(|specifier: &str, _referrer: &str| {
        (specifier == "parked").then(|| {
            (
                "parked".to_string(),
                "export const ready = 1; await new Promise(() => {});".to_string(),
            )
        })
    });
    eval_to_string(
        &mut engine,
        "globalThis.held = new ShadowRealm(); held.importValue('parked', 'ready'); 0",
    );
    let parked: usize = engine
        .interp
        .shadow_realms
        .values()
        .map(|realm| {
            engine
                .interp
                .with_realm_view(realm.id(), |child| child.generators.len())
        })
        .sum();
    assert!(parked > 0, "the realm holds a parked module body");
    eval_to_string(&mut engine, "held = undefined; 0");
    engine.interp.gc_collect();
    assert!(engine.interp.shadow_realms.is_empty());
}

#[test]
fn ordinary_symbols_are_retained_only_by_live_values_and_property_keys() {
    let mut engine = Engine::new();
    let baseline = engine.interp.symbol_agent.borrow().symbols.len();
    engine
        .eval(
            "(() => { const symbol = Symbol('property-only');
                       globalThis.symbolHolder = { [symbol]: 1 }; })()",
            false,
        )
        .expect("symbol-key setup parses");
    // The strong handle stays in a helper frame (the collector scans the stack).
    let weak = crate::gc_test::in_frame(|| {
        let held = engine
            .interp
            .symbol_agent
            .borrow()
            .symbols
            .values()
            .filter_map(|weak| weak.upgrade())
            .find(|symbol| symbol.description.as_deref() == Some("property-only"))
            .expect("symbol property key owns its identity");
        crate::value::symbol_downgrade(&held)
    });

    engine.interp.gc_collect();
    assert!(
        crate::gc_test::alive(&weak),
        "live property key lost its Symbol"
    );
    assert!(matches!(
        engine
            .eval(
                "var recovered = Object.getOwnPropertySymbols(symbolHolder)[0];
                 recovered.description + ':' + symbolHolder[recovered]",
                false,
            )
            .expect("property-key recovery parses"),
        Completion::Value(ref value) if value == "property-only:1"
    ));

    engine
        .eval(
            "delete symbolHolder[recovered]; recovered = null; symbolHolder = null",
            false,
        )
        .expect("symbol-key release parses");
    engine.interp.gc_collect();
    assert!(
        !crate::gc_test::alive(&weak),
        "deleted property retained its Symbol"
    );

    // Symbol allocation alone must not become a permanent identity registry. The collector also
    // prunes weak lookup headers, returning to the baseline after transient churn.
    engine
        .eval("for (let i = 0; i < 10000; i++) Symbol('transient')", false)
        .expect("symbol churn parses");
    engine.interp.gc_collect();
    assert_eq!(engine.interp.symbol_agent.borrow().symbols.len(), baseline);

    // In contrast, the Agent's GlobalSymbolRegistry is normatively append-only and strong.
    engine
        .eval("Symbol.for('registry-kept')", false)
        .expect("registered symbol parses");
    let registered = crate::value::symbol_downgrade(
        &engine.interp.symbol_agent.borrow().global_by_key["registry-kept"],
    );
    engine.interp.gc_collect();
    assert!(crate::gc_test::alive(&registered));
    assert_eq!(
        run("Symbol.keyFor(Symbol.for('registry-kept'))"),
        "registry-kept"
    );
}

#[test]
fn temporary_symbol_property_keys_keep_their_identity() {
    // ECMA-262 ToPropertyKey returns an actual Symbol, and OrdinaryOwnPropertyKeys must later
    // return that same identity. None of these keys has a variable or registry as a second owner.
    assert_eq!(
        run("var o={}; o[Symbol('assignment')]=1;
             Object.getOwnPropertySymbols(o)[0].description"),
        "assignment"
    );
    assert_eq!(
        run("var o={ [Symbol('literal')]: 1 };
             Object.getOwnPropertySymbols(o)[0].description"),
        "literal"
    );
    assert_eq!(
        run(
            "var o={}; o[{[Symbol.toPrimitive](){return Symbol('coerced')}}]=1;
             Object.getOwnPropertySymbols(o)[0].description"
        ),
        "coerced"
    );
    assert_eq!(
        run("var o={}; o[Symbol('proxy')]=1; var p=new Proxy(o,{});
             [Object.keys(p).length, typeof Reflect.ownKeys(p)[0],
              Reflect.ownKeys(p)[0].description].join(',')"),
        "0,symbol,proxy"
    );
    assert_eq!(
        run("var got=false;
             Reflect.set(new Proxy({}, {set(t,k){got=typeof k==='symbol';return true}}),
                         Symbol(), 1); got"),
        "true"
    );
    assert_eq!(
        run("var C=class { [Symbol('method')](){} [Symbol('field')]=1 };
             var c=new C; Object.getOwnPropertySymbols(C.prototype)[0].description+','+
             Object.getOwnPropertySymbols(c)[0].description"),
        "method,field"
    );
}

#[test]
fn template_with_comments_in_substitution() {
    // Comments inside `${...}` (esp. with apostrophes) must lex cleanly.
    assert_eq!(run("`${ 1 /* a's */ + 2 }`"), "3");
    assert_eq!(run("let x=5; `${ x // it's x\n}`"), "5");
}

#[test]
fn array_methods() {
    assert_eq!(run("[1,2,3,4].find(x=>x>2)"), "3");
    assert_eq!(run("[1,2,3,4].findIndex(x=>x>2)"), "2");
    assert_eq!(run("[1,2,3].some(x=>x>2)"), "true");
    assert_eq!(run("[1,2,3].every(x=>x>0)"), "true");
    assert_eq!(run("[3,1,2].sort().join(',')"), "1,2,3");
    assert_eq!(run("[3,1,2,10].sort((a,b)=>a-b).join(',')"), "1,2,3,10");
    assert_eq!(run("[1,2,3].at(-1)"), "3");
    assert_eq!(run("[1,[2,[3]]].flat(2).join(',')"), "1,2,3");
    assert_eq!(run("[1,2,3].flatMap(x=>[x,x]).join(',')"), "1,1,2,2,3,3");
    assert_eq!(
        run("var a=[1,2,3,4]; a.splice(1,2,'x'); a.join(',')"),
        "1,x,4"
    );
    assert_eq!(run("[1,2,3].fill(0,1).join(',')"), "1,0,0");
    assert_eq!(run("Array.from('abc').join(',')"), "a,b,c");
    assert_eq!(run("Array.from([1,2,3], x=>x*2).join(',')"), "2,4,6");
    assert_eq!(
        run("Array.from({length:3, 0:'a',1:'b',2:'c'}).join(',')"),
        "a,b,c"
    );
}

#[test]
fn iterator_protocol() {
    assert_eq!(run("[...[1,2,3].keys()].join(',')"), "0,1,2");
    assert_eq!(
        run("[...[10,20].entries()].map(e=>e.join(':')).join(',')"),
        "0:10,1:20"
    );
    assert_eq!(run("typeof [][Symbol.iterator]"), "function");
    assert_eq!(
        run("var a=[1,undefined,3]; [...a].map(x=>x===undefined?'u':x).join(',')"),
        "1,u,3"
    );
    let custom = "let obj = { [Symbol.iterator]() { let n=0; return { next(){ return n<3 ? {value:n++,done:false} : {value:undefined,done:true}; } }; } };";
    assert_eq!(
        run(&format!("{custom} let s=0; for (const x of obj) s+=x; s")),
        "3"
    );
    assert_eq!(run(&format!("{custom} [...obj].join(',')")), "0,1,2");
    // SpreadEvaluation performs GetIterator even for arrays; a customized @@iterator must not
    // be bypassed by the dense-array fast path (ECMA-262 section 13.2.4.1).
    assert_eq!(
        run("var a=[1,2]; a[Symbol.iterator]=function*(){yield 9; yield 8}; [...a].join(',')"),
        "9,8"
    );
    assert_eq!(
        run("Array.prototype[Symbol.iterator]=function*(){yield 7}; [...[1,2]].join(',')"),
        "7"
    );
    // Primitive strings likewise consult the mutable String.prototype @@iterator property.
    assert_eq!(
        run("String.prototype[Symbol.iterator]=function*(){yield 'x'; yield 'y'}; [...'ab'].join(',')"),
        "x,y"
    );
    assert_eq!(
        run("String.prototype[Symbol.iterator]=function*(){yield 'x'; yield 'y'}; var out=''; for (var c of 'ab') out+=c; out"),
        "xy"
    );
    assert_eq!(
        run("String.prototype[Symbol.iterator]=function*(){yield 'x'; yield 'y'}; var [a,b]='ab'; a+b"),
        "xy"
    );
    // ArrayAccumulation uses ?IteratorStepValue, not IteratorClose. next/done/value failures
    // mark the record done and propagate without looking up return (ECMA-262 snapshot e28783d).
    assert_eq!(
        run("var closed=false; var src={[Symbol.iterator](){var n=0; return {next(){if(n++) throw Error('boom'); return {value:1,done:false}},return(){closed=true; throw Error('close')}}}}; try{[...src]}catch(e){} closed"),
        "false"
    );
    assert_eq!(
        run("var closed=false; var src={[Symbol.iterator](){return {next:1,return(){closed=true;return {}}}}}; try{[...src]}catch(e){} closed"),
        "false"
    );
}

#[test]
fn json_and_reflect() {
    assert_eq!(
        run("JSON.stringify({a:1,b:[2,3],c:'x'})"),
        "{\"a\":1,\"b\":[2,3],\"c\":\"x\"}"
    );
    assert_eq!(
        run("JSON.stringify([1,null,true,'s'])"),
        "[1,null,true,\"s\"]"
    );
    assert_eq!(
        run("JSON.stringify({a:undefined,b:function(){},c:1})"),
        "{\"c\":1}"
    );
    assert_eq!(run("JSON.parse('{\"a\":1,\"b\":[2,3]}').b[1]"), "3");
    assert_eq!(run("JSON.parse('\"hi\\\\n\"').length"), "3");
    // ASCII source uses the byte parser, while direct Unicode and escaped surrogate pairs keep
    // the UTF-16-safe path and representation.
    assert_eq!(run("JSON.parse('\"caf\u{00E9}\"')"), "café");
    assert_eq!(run("JSON.parse('\"\\\\uD83D\\\\uDE00\"')"), "😀");
    assert_eq!(run("JSON.parse('\"\\\\uD800\"').length"), "1");
    assert_eq!(run("JSON.stringify({a:1}, null, 2)"), "{\n  \"a\": 1\n}");
    assert_eq!(throws("var o={}; o.self=o; JSON.stringify(o)"), "TypeError");
    assert_eq!(run("Reflect.has({a:1}, 'a')"), "true");
    assert_eq!(run("Reflect.get({x:7}, 'x')"), "7");
    assert_eq!(run("var o={}; Reflect.set(o,'k',9); o.k"), "9");
    assert_eq!(run("Reflect.ownKeys({a:1,b:2}).join(',')"), "a,b");
    assert_eq!(run("Reflect.apply((a,b)=>a+b, null, [3,4])"), "7");
}

#[test]
fn map_and_set() {
    assert_eq!(
        run("var m = new Map(); m.set('a',1).set('b',2); m.get('b')"),
        "2"
    );
    assert_eq!(run("var m = new Map([['x',10],['y',20]]); m.size"), "2");
    assert_eq!(run("var m = new Map(); m.set(1,'a'); m.has(1)"), "true");
    assert_eq!(
        run("var m = new Map([['a',1]]); m.delete('a'); m.size"),
        "0"
    );
    // ECMA-262 §24.1.3.1 preserves [[MapData]]'s positions when clear() runs:
    // an iterator suspended in the old list skips the emptied entries and can
    // still observe entries appended afterwards.
    assert_eq!(
        run("var m=new Map([['a',1],['b',2]]), it=m.keys(); it.next(); m.clear(); m.set('c',3); var n=it.next(); n.value+':'+n.done"),
        "c:false"
    );
    assert_eq!(
        run("var s=new Set(['a','b']), it=s.values(); it.next(); s.clear(); s.add('c'); var n=it.next(); n.value+':'+n.done"),
        "c:false"
    );
    assert_eq!(
        run("var m = new Map([['a',1],['b',2]]); [...m.keys()].join(',')"),
        "a,b"
    );
    assert_eq!(
        run("var m = new Map([['a',1],['b',2]]); var s=0; m.forEach(v=>s+=v); s"),
        "3"
    );
    assert_eq!(run("var s = new Set([1,2,2,3,3,3]); s.size"), "3");
    assert_eq!(
        run("var s = new Set(); s.add(1).add(1); s.has(1) && s.size===1"),
        "true"
    );
    assert_eq!(run("[...new Set([3,1,2])].join(',')"), "3,1,2");
    assert_eq!(
        run("var w = new WeakMap(); var k={}; w.set(k,5); w.get(k)"),
        "5"
    );
    assert_eq!(throws("new WeakMap().set('str', 1)"), "TypeError"); // non-object key
    assert_eq!(
        run("NaN === NaN ? 'x' : (new Set([NaN]).has(NaN) ? 'svz' : 'no')"),
        "svz"
    );
    assert_eq!(
        run(
            "var object={}, symbol=Symbol('key'), text=['same'].join('');
             var m=new Map([[undefined,1],[null,2],[true,3],[NaN,4],[-0,5],
                            [123456789012345678901234567890n,6],[text,7],[symbol,8],[object,9]]);
             [m.size,m.get(Number('nope')),m.get(+0),m.get('same'),m.get(symbol),m.get(object)].join(',')"
        ),
        "9,4,5,7,8,9"
    );
}

#[test]
fn map_hash_index_tracks_large_delete_and_reinsert_workloads() {
    // ECMA-262 §24.1 requires average-sublinear Map access. Exercise enough
    // entries to catch an accidental return to linear scans while also
    // verifying that delete leaves a tombstone and reinsertion appends a new
    // ordered entry with the updated value.
    assert_eq!(
        run("var m = new Map();
             for (var i = 0; i < 20000; i++) m.set(i, i);
             for (var i = 0; i < 20000; i += 2) m.delete(i);
             for (var i = 0; i < 20000; i += 2) m.set(i, -i);
             [m.size, m.get(19998), m.get(19999),
              Array.from(m.keys()).slice(-3).join(',')].join(':')"),
        "20000:-19998:19999:19994,19996,19998"
    );
}

#[test]
fn dates_follow_the_system_time_zone() {
    // ECMA-262 #sec-localtime, #sec-utc-t, #sec-timezoneestring and
    // #sec-date-time-string-format over SystemTimeZoneIdentifier; the expected
    // values are V8's (Node) with TZ set to each zone.
    struct Zone;
    impl Drop for Zone {
        fn drop(&mut self) {
            crate::builtins::TEST_TIME_ZONE.with(|zone| zone.set(None));
        }
    }
    let _reset = Zone;
    crate::builtins::TEST_TIME_ZONE.with(|zone| zone.set(Some("Europe/Berlin")));
    let d = "new Date(Date.UTC(2026, 9, 3, 12, 34, 56))";
    assert_eq!(
        run(&format!("{d}.toString()")),
        "Sat Oct 03 2026 14:34:56 GMT+0200 (Central European Summer Time)"
    );
    assert_eq!(
        run(&format!("{d}.getHours() + ':' + {d}.getUTCHours()")),
        "14:12"
    );
    assert_eq!(run(&format!("{d}.getTimezoneOffset()")), "-120");
    assert_eq!(run("new Date(2026, 0, 15).getTimezoneOffset()"), "-60");
    assert_eq!(
        run("new Date(2026, 9, 3, 12).toISOString()"),
        "2026-10-03T10:00:00.000Z"
    );
    // A skipped local time reads with the earlier offset; a repeated one is
    // its earlier instant.
    assert_eq!(
        run("new Date(2026, 2, 29, 2, 30).toString()"),
        "Sun Mar 29 2026 03:30:00 GMT+0200 (Central European Summer Time)"
    );
    assert_eq!(
        run("new Date(2026, 9, 25, 2, 30).toISOString()"),
        "2026-10-25T00:30:00.000Z"
    );
    assert_eq!(run("Date.parse('2026-10-03T12:00:00')"), "1791021600000");
    assert_eq!(run("Date.parse('2026-10-03')"), "1790985600000");
    assert_eq!(run("Date.parse('Oct 3 2026 12:00:00')"), "1791021600000");
    assert_eq!(
        run("Date.parse('Sat, 03 Oct 2026 12:00:00 GMT')"),
        "1791028800000"
    );
    assert_eq!(
        run("var e = new Date(2026, 9, 3, 12); e.setHours(23); e.toISOString()"),
        "2026-10-03T21:00:00.000Z"
    );
    assert_eq!(
        run("var f = new Date(NaN); f.setFullYear(2020); f.toISOString()"),
        "2019-12-31T23:00:00.000Z"
    );
    assert_eq!(
        run("Intl.DateTimeFormat().resolvedOptions().timeZone"),
        "Europe/Berlin"
    );
    assert_eq!(
        run(&format!(
            "new Intl.DateTimeFormat('en-US', {{timeZoneName: 'long'}}).format({d})"
        )),
        "10/3/2026, Central European Summer Time"
    );
    assert_eq!(
        run(&format!(
            "new Intl.DateTimeFormat('en-US', {{timeZoneName: 'short', hour: 'numeric'}}).format({d})"
        )),
        "2 PM GMT+2"
    );
    crate::builtins::TEST_TIME_ZONE.with(|zone| zone.set(Some("America/New_York")));
    assert_eq!(
        run("new Date(Date.UTC(2026, 2, 8, 7, 30)).toString()"),
        "Sun Mar 08 2026 03:30:00 GMT-0400 (Eastern Daylight Time)"
    );
    assert_eq!(
        run("new Date(2026, 2, 8, 2, 30).toISOString()"),
        "2026-03-08T07:30:00.000Z"
    );
    assert_eq!(
        run("new Date(2026, 10, 1, 1, 30).toISOString()"),
        "2026-11-01T05:30:00.000Z"
    );
    assert_eq!(run("new Date(2026, 0, 15).getTimezoneOffset()"), "300");
}

#[test]
fn dates_follow_the_zone_rule_after_the_last_tabulated_transition() {
    // RFC 9636 section 3.3: the TZif footer TZ string governs local time after the last
    // transition, so daylight saving time continues after 2037. Expected values are V8's
    // (Node, ICU 78) with TZ set to each zone; the Temporal transitions are CPython zoneinfo's.
    struct Zone;
    impl Drop for Zone {
        fn drop(&mut self) {
            crate::builtins::TEST_TIME_ZONE.with(|zone| zone.set(None));
        }
    }
    let _reset = Zone;
    crate::builtins::TEST_TIME_ZONE.with(|zone| zone.set(Some("Europe/Berlin")));
    assert_eq!(
        run("new Date(2040, 6, 1, 12).toString()"),
        "Sun Jul 01 2040 12:00:00 GMT+0200 (Central European Summer Time)"
    );
    assert_eq!(run("new Date(2040, 6, 1, 12).getTimezoneOffset()"), "-120");
    assert_eq!(run("new Date(2040, 0, 1, 12).getTimezoneOffset()"), "-60");
    crate::builtins::TEST_TIME_ZONE.with(|zone| zone.set(Some("America/New_York")));
    assert_eq!(
        run("new Date(Date.UTC(2050, 6, 1)).toString()"),
        "Thu Jun 30 2050 20:00:00 GMT-0400 (Eastern Daylight Time)"
    );
    // A skipped and a repeated local time after the table, as in #sec-utc-t.
    assert_eq!(
        run("new Date(2050, 2, 13, 2, 30).toISOString()"),
        "2050-03-13T07:30:00.000Z"
    );
    assert_eq!(
        run("new Date(2050, 10, 6, 1, 30).toISOString()"),
        "2050-11-06T05:30:00.000Z"
    );
    assert_eq!(
        run(
            "['2045-01-15', '2045-07-15'].map(d => new Intl.DateTimeFormat('en-US', \
             {timeZone: 'Australia/Sydney', hour: 'numeric', timeZoneName: 'longOffset'}) \
             .format(new Date(d))).join('|')"
        ),
        "11 AM GMT+11:00|10 AM GMT+10:00"
    );
    assert_eq!(
        run(
            "Temporal.ZonedDateTime.from('2037-12-01T12:00[Europe/Berlin]') \
             .getTimeZoneTransition('next').toString()"
        ),
        "2038-03-28T03:00:00+02:00[Europe/Berlin]"
    );
    assert_eq!(
        run(
            "Temporal.ZonedDateTime.from('2040-01-01T00:00[Europe/Berlin]') \
             .getTimeZoneTransition('previous').toString()"
        ),
        "2039-10-30T02:00:00+01:00[Europe/Berlin]"
    );
    assert_eq!(
        run(
            "Temporal.ZonedDateTime.from('2045-06-01T00:00[America/Santiago]') \
             .getTimeZoneTransition('next').toString()"
        ),
        "2045-09-03T01:00:00-03:00[America/Santiago]"
    );
    assert_eq!(
        run("Temporal.ZonedDateTime.from('2050-07-01T12:00[America/New_York]').offset"),
        "-04:00"
    );
    // The rule never stops, but a transition after nsMaxInstant is null.
    assert_eq!(
        run(
            "new Temporal.ZonedDateTime(8640000000000000000000n, 'Europe/Berlin') \
             .getTimeZoneTransition('next')"
        ),
        "null"
    );
    assert_eq!(
        run(
            "new Temporal.ZonedDateTime(8639968464000000000000n, 'Europe/Berlin') \
             .getTimeZoneTransition('next') === null"
        ),
        "false"
    );
}

#[test]
fn dates() {
    assert_eq!(run("new Date(0).toISOString()"), "1970-01-01T00:00:00.000Z");
    // Two-digit years in the implementation-specific formats, as V8 and
    // SpiderMonkey read them (test262 staging/sm/Date/two-digit-years.js).
    assert_eq!(
        run("[new Date('1/2/50'), new Date('50/1/2'), new Date('may 1 49')].map(d => d.getFullYear()).join()"),
        "1950,1950,2049"
    );
    assert_eq!(
        run("[new Date('13/1/1'), new Date('99/1/99'), new Date('may 1999 1999'), new Date('may 0 0')].map(Number).join()"),
        "NaN,NaN,NaN,NaN"
    );
    assert_eq!(
        run("new Date(Date.UTC(2020, 0, 15)).getUTCFullYear()"),
        "2020"
    );
    assert_eq!(run("new Date(Date.UTC(2020, 5, 15)).getUTCMonth()"), "5");
    assert_eq!(
        run("Date.parse('2021-06-15T12:30:00.000Z')"),
        "1623760200000"
    );
    assert_eq!(
        run("new Date('2000-01-01T00:00:00Z').getTime()"),
        "946684800000"
    );
    assert_eq!(
        run("var d = new Date(0); d.setUTCFullYear(1999); d.getUTCFullYear()"),
        "1999"
    );
    assert_eq!(run("new Date(NaN).toString()"), "Invalid Date");
    assert_eq!(
        run("JSON.stringify({t: new Date(0)})"),
        "{\"t\":\"1970-01-01T00:00:00.000Z\"}"
    );
    assert_eq!(run("typeof Date.now()"), "number");
    assert_eq!(run("new Date(Date.UTC(2023,11,25)).getUTCDay()"), "1"); // Monday
}

#[test]
fn internal_slots_are_not_properties() {
    // Internal slots (ECMA-262 #sec-object-internal-methods-and-internal-slots) are not
    // properties: reflection never lists them, author properties cannot forge them, and
    // integrity levels ignore them. The expected values are Node's.
    let source = r#"
        var names = function (o) { return Object.getOwnPropertyNames(o).join(); };
        /(a)(b)/.exec("xab");
        var resolve;
        Promise.all([{ then: function (r) { resolve = r; } }]);
        var date = Object.freeze(new Date(5));
        date.setTime(7);
        var forged = Object.create(Date.prototype);
        forged.__date_ms = 1;
        var forgedOk;
        try { forged.getTime(); forgedOk = true; } catch (e) { forgedOk = false; }
        [
            names(new Date(0)),
            names(new Intl.NumberFormat()),
            names(new Intl.DateTimeFormat()),
            names(new Intl.Locale("en-US")),
            names(new ArrayBuffer(4, { maxByteLength: 8 })),
            names(new DataView(new ArrayBuffer(2))),
            names([1].values().map(function (x) { return x; })),
            names("ab".matchAll(/a/g)),
            names(new DisposableStack()),
            names(RegExp).indexOf("legacy") < 0,
            RegExp.$1 + RegExp.$2 + RegExp.lastMatch,
            date.getTime(),
            Object.isFrozen(date),
            Object.isFrozen(Object.preventExtensions(new Date())),
            forgedOk,
            new Intl.Locale("en-US", { hourCycle: "h23" }).hourCycle,
        ].join("|")
    "#;
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        assert_eq!(
            run_in(&mut engine, source),
            "|||||||||true|abab|7|true|true|false|h23",
            "tier {tier:?}"
        );
        // PerformPromiseAll (#sec-performpromiseall) hands `then` its resolve element function
        // from a later job.
        assert_eq!(
            run_in(&mut engine, "names(resolve)"),
            "length,name",
            "tier {tier:?}"
        );
    }
}

#[cfg(feature = "embed")]
#[test]
fn wall_clocks_are_mutable_and_realm_local() {
    use std::cell::Cell;
    use std::rc::Rc;

    fn read_times(engine: &mut Engine) -> String {
        match engine
            .eval(
                "[Date.now(), +new Date(), Temporal.Now.instant().epochMilliseconds].join('|')",
                false,
            )
            .expect("parse")
        {
            Completion::Value(value) => value,
            Completion::Throw { name, message } => panic!("threw {name}: {message}"),
        }
    }

    let first_now = Rc::new(Cell::new(1_234.9));
    let mut first = Engine::new();
    let first_clock = first_now.clone();
    first.set_wall_clock(move || first_clock.get());
    assert_eq!(read_times(&mut first), "1234|1234|1234");

    first_now.set(5_678.1);
    assert_eq!(read_times(&mut first), "5678|5678|5678");

    let mut second = Engine::new();
    second.set_wall_clock(|| 42.0);
    assert_eq!(read_times(&mut second), "42|42|42");
    assert_eq!(read_times(&mut first), "5678|5678|5678");
}

#[cfg(feature = "embed")]
#[test]
fn embedder_realms_isolate_intrinsics_and_native_globals() {
    fn realm_marker<'s>(
        ctx: &mut Ctx<'s>,
        _this: Value<'s>,
        _args: &[Value<'s>],
    ) -> Result<Value<'s>, Value<'s>> {
        Ok(ctx.str("child"))
    }

    let mut engine = Engine::new();
    let rendered = engine.scope(|cx| {
        let main = cx.global_this();
        let child = cx.create_embed_realm();
        let installed = cx
            .with_embed_realm(&child, |ctx| {
                ctx.define_embed_global("realmMarker", 0, realm_marker);
                matches!(
                    ctx.eval_classic_script_interruptible(
                        "Array.prototype.realmOnly = 1; globalThis.authorOnly = 2;",
                    ),
                    Ok(Ok(_))
                )
            })
            .unwrap_or_else(|_| panic!("enter child realm"));
        assert!(installed, "child setup completes");

        assert!(
            matches!(
                (cx.member_get(&main, "realmMarker")).map(|__value| (__value).kind()),
                Ok(ValueKind::Undefined)
            ),
            "native global stays out of the main realm"
        );
        let child_result = cx
            .with_embed_realm(&child, |ctx| {
                match ctx.eval_classic_script_interruptible(
                    "[realmMarker(), authorOnly, Array.prototype.realmOnly].join('|')",
                ) {
                    Ok(Ok(value)) => Some(value),
                    _ => None,
                }
            })
            .unwrap_or_else(|_| panic!("re-enter child realm"))
            .unwrap_or_else(|| panic!("child script completes"));
        text_of(cx, &child_result)
    });
    assert_eq!(rendered, "child|2|1");
    match engine
        .eval(
            "String(typeof realmMarker) + '|' + String(typeof authorOnly) + '|' + String(Array.prototype.realmOnly)",
            false,
        )
        .expect("main parse")
    {
        Completion::Value(value) => assert_eq!(value, "undefined|undefined|undefined"),
        Completion::Throw { name, message } => panic!("main threw {name}: {message}"),
    }
}

#[cfg(feature = "embed")]
#[test]
fn entered_realms_stay_active_until_left_and_nest() {
    fn current_context<'s>(
        ctx: &mut Ctx<'s>,
        _this: Value<'s>,
        _args: &[Value<'s>],
    ) -> Result<Value<'s>, Value<'s>> {
        Ok(Value::Num(ctx.host_job_context() as f64))
    }

    let mut engine = Engine::new();
    engine.set_host_job_context(1);
    engine.scope(|cx| cx.define_embed_global("currentHostContext", 0, current_context));
    // A Realm's global, held by a handle: the entries are made at the Engine level.
    let realm = |engine: &mut Engine, context: u64| {
        engine.scope(|cx| {
            let global = cx.create_embed_realm();
            cx.with_embed_realm(&global, |ctx| {
                ctx.set_host_job_context(context);
                ctx.define_embed_global("currentHostContext", 0, current_context);
            })
            .unwrap_or_else(|_| panic!("set up realm {context}"));
            crate::embed::Handle::new(cx, &global).expect("a handle to the realm's global")
        })
    };
    let first = realm(&mut engine, 2);
    let second = realm(&mut engine, 3);
    let read = |engine: &mut Engine| match engine
        .eval("String(currentHostContext()) + ':' + typeof marker", false)
        .unwrap_or_else(|error| panic!("parse: {error:?}"))
    {
        Completion::Value(value) => value,
        Completion::Throw { name, message } => panic!("threw {name}: {message}"),
    };

    let outer = engine
        .enter_realm(&first)
        .unwrap_or_else(|_| panic!("enter first"));
    // The embedder's own work runs between entering and leaving.
    assert!(matches!(
        engine.eval("globalThis.marker = 1", false),
        Ok(Completion::Value(_))
    ));
    assert_eq!(read(&mut engine), "2:number");
    let inner = engine
        .enter_realm(&second)
        .unwrap_or_else(|_| panic!("enter second"));
    assert_eq!(read(&mut engine), "3:undefined");
    engine.leave_realm(inner);
    assert_eq!(read(&mut engine), "2:number");
    engine.leave_realm(outer);
    assert_eq!(read(&mut engine), "1:undefined");
    let number = engine.scope(|cx| {
        assert!(cx.enter_realm(&Value::Num(1.0)).is_err(), "not a Realm");
        crate::embed::Handle::new(cx, &Value::Num(1.0)).expect("a primitive's handle")
    });
    assert_eq!(
        engine.enter_realm(&number).err(),
        Some(crate::RealmError::NotARealm)
    );
}

#[cfg(feature = "embed")]
#[test]
fn embedder_realm_snapshot_and_host_context_restore_are_isolated() {
    fn current_context<'s>(
        ctx: &mut Ctx<'s>,
        _this: Value<'s>,
        _args: &[Value<'s>],
    ) -> Result<Value<'s>, Value<'s>> {
        Ok(Value::Num(ctx.host_job_context() as f64))
    }

    let mut engine = Engine::new();
    let snapshot = crate::compile_snapshot(
        "globalThis.snapshotRealmValue = Array.prototype.snapshotRealmOnly = 7;",
    )
    .unwrap_or_else(|error| panic!("compile snapshot: {error}"));

    engine.set_host_job_context(41);
    let child = engine.scope(|cx| {
        let child = cx.create_embed_realm();
        let completed = cx
            .with_embed_realm(&child, |ctx| {
                ctx.set_host_job_context(42);
                ctx.define_embed_global("currentHostContext", 0, current_context);
                matches!(
                    ctx.eval_classic_snapshot_interruptible(&snapshot),
                    Ok(Ok(_))
                )
            })
            .unwrap_or_else(|_| panic!("enter child realm"));
        assert!(completed);
        assert_eq!(cx.host_job_context(), 41);
        crate::embed::Handle::new(cx, &child).expect("a handle to the child's global")
    });

    let engine_level = engine
        .with_embed_realm(&child, |engine| {
            engine.eval("currentHostContext() + '|' + snapshotRealmValue", false)
        })
        .unwrap_or_else(|_| panic!("enter child Realm through Engine"))
        .unwrap_or_else(|error| panic!("engine-level child parse: {error:?}"));
    assert!(matches!(
        engine_level,
        Completion::Value(value) if value == "42|7"
    ));
    assert_eq!(engine.host_job_context(), 41);

    engine.scope(|cx| {
        let child = child.get(cx).expect("the engine's handle");
        cx.with_embed_realm(&child, |ctx| {
            ctx.eval_classic_script_interruptible(
                "globalThis.readChildRealm = function () { return currentHostContext() + '|' + snapshotRealmValue; }; class ChildEventTarget {} globalThis.ChildEventTarget = ChildEventTarget; ChildEventTarget.prototype.realmProbe = function () { return currentHostContext() + '|' + snapshotRealmValue; };",
            )
        })
        .unwrap_or_else(|_| panic!("install child reader"))
        .unwrap_or_else(|error| panic!("parse child reader: {error:?}"))
        .unwrap_or_else(|_| panic!("child reader setup threw"));
        let reader = cx
            .member_get(&child, "readChildRealm")
            .unwrap_or_else(|_| panic!("read child function"));
        let cross_realm_result = cx
            .call_function(&reader, child, &[])
            .unwrap_or_else(|_| panic!("call child function from main Realm"));
        assert_eq!(text_of(cx, &cross_realm_result), "42|7");
        assert_eq!(cx.host_job_context(), 41);
        let main = cx.global_this();
        cx.member_set(&main, "childRealm", child)
            .unwrap_or_else(|_| panic!("expose child global to main Realm"));
    });
    assert!(matches!(
        engine
            .eval("childRealm.readChildRealm()", false)
            .unwrap_or_else(|error| panic!("main cross-Realm expression: {error:?}")),
        Completion::Value(value) if value == "42|7"
    ));
    assert_eq!(engine.host_job_context(), 41);
    assert!(matches!(
        engine
            .eval("new childRealm.ChildEventTarget().realmProbe()", false)
            .unwrap_or_else(|error| panic!("main cross-Realm construct expression: {error:?}")),
        Completion::Value(value) if value == "42|7"
    ));
    assert_eq!(engine.host_job_context(), 41);

    assert!(matches!(
        engine
            .eval(
                "String(typeof snapshotRealmValue) + '|' + String(Array.prototype.snapshotRealmOnly)",
                false,
            )
            .unwrap_or_else(|error| panic!("main eval: {error:?}")),
        Completion::Value(value) if value == "undefined|undefined"
    ));

    let child_result = engine.scope(|cx| {
        let child = child.get(cx).expect("the engine's handle");
        let result = cx
            .with_embed_realm(&child, |ctx| {
                ctx.set_host_job_context(42);
                ctx.eval_classic_script_interruptible(
                    "String(snapshotRealmValue) + '|' + String(Array.prototype.snapshotRealmOnly)",
                )
            })
            .unwrap_or_else(|_| panic!("re-enter child realm"))
            .unwrap_or_else(|error| panic!("parse child script: {error:?}"))
            .unwrap_or_else(|_| panic!("child script threw"));
        text_of(cx, &result)
    });
    assert_eq!(child_result, "7|7");
    assert_eq!(engine.host_job_context(), 41);
}

#[cfg(feature = "embed")]
#[test]
fn job_callbacks_capture_registration_source_without_changing_execution_realm() {
    fn caller<'s>(
        ctx: &mut Ctx<'s>,
        _this: Value<'s>,
        _args: &[Value<'s>],
    ) -> Result<Value<'s>, Value<'s>> {
        Ok(ctx.script_caller_global())
    }
    fn then<'s>(
        ctx: &mut Ctx<'s>,
        _this: Value<'s>,
        args: &[Value<'s>],
    ) -> Result<Value<'s>, Value<'s>> {
        let source = ctx.script_caller_global();
        ctx.invoke(args[0], Value::Undefined, &[source])
    }
    fn throw_source<'s>(
        ctx: &mut Ctx<'s>,
        _this: Value<'s>,
        _args: &[Value<'s>],
    ) -> Result<Value<'s>, Value<'s>> {
        Err(ctx.script_caller_global())
    }
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        for browser in [false, true] {
            let mut engine = Engine::new();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            if browser {
                engine.set_job_callback_script_caller_capture(true);
            }
            engine.define_global("callerGlobal", 0, caller);
            engine.define_global("nativeThen", 2, then);
            engine.define_global("throwSource", 0, throw_source);
            run_in(
                &mut engine,
                r#"
                globalThis.trace = [];
                globalThis.userCaller = () => callerGlobal();
                globalThis.pending = new Promise(r => globalThis.release = r);
                globalThis.rejected = new Promise((r, j) => globalThis.fail = j);
            "#,
            );
            let child = engine.scope(|cx| {
                let main = cx.global_this();
                let child = cx.create_embed_realm();
                cx.member_set(&child, "main", main)
                    .unwrap_or_else(|_| panic!("parent"));
                cx.member_set(&child, "browserHost", Value::Bool(browser))
                    .unwrap_or_else(|_| panic!("mode"));
                crate::embed::Handle::new(cx, &child).expect("a handle to the child's global")
            });
            engine.with_embed_realm(&child, |engine| run_in(engine, r#"
                const expected = browserHost ? globalThis : main;
                const check = (label, expected) => value => main.trace.push(label + ':' + (value === expected));
                Promise.resolve().then(main.callerGlobal.bind(main)).then(check('bound', expected));
                Promise.reject(1).catch(main.callerGlobal).then(check('reject', expected));
                main.pending.then(main.callerGlobal).then(check('pending', expected));
                main.rejected.catch(main.callerGlobal).then(check('pending-reject', expected));
                Promise.resolve({then: main.nativeThen}).then(check('thenable', expected));
                Promise.resolve().then(main.throwSource).catch(check('throw', expected));
                Promise.resolve().then(main.userCaller).then(check('user', main));
                Promise.resolve().then(new Proxy(main.callerGlobal, {})).then(check('proxy', expected));
            "#)).unwrap_or_else(|_| panic!("child registration"));
            // Settlement happens in a different script/Realm after the original registration.
            run_in(&mut engine, "release(); fail();");
            assert_eq!(run_in(&mut engine, "trace.sort().join('|')"),
                "bound:true|pending-reject:true|pending:true|proxy:true|reject:true|thenable:true|throw:true|user:true",
                "{tier:?}, browser={browser}");
            assert_eq!(
                run_in(&mut engine, "callerGlobal() === globalThis"),
                "true",
                "source restored"
            );
        }
    }
}

#[cfg(feature = "embed")]
#[test]
fn job_callback_source_realms_are_traced_and_collectable() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        for kind in ["promise", "finalization"] {
            let mut engine = Engine::new();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            engine.set_job_callback_script_caller_capture(true);
            engine.define_global("nothing", 0, |_ctx, _, _| Ok(Value::Undefined));
            // The callback itself belongs to the main Realm. Only its HostDefined source
            // retains the child, whose global also owns the pending promise / registry.
            let source = if kind == "promise" {
                "globalThis.saved = new main.Promise(() => {}); saved.then(main.nothing); main.kept = saved;"
            } else {
                "globalThis.saved = new main.FinalizationRegistry(main.nothing); main.kept = saved;"
            };
            // The child Realm's handle lives only in this helper frame (the collector scans the
            // stack).
            crate::gc_test::in_frame(|| {
                let child = engine.scope(|cx| {
                    let main = cx.global_this();
                    let child = cx.create_embed_realm();
                    cx.member_set(&child, "main", main)
                        .unwrap_or_else(|_| panic!("parent"));
                    crate::embed::Handle::new(cx, &child).expect("a handle")
                });
                engine
                    .with_embed_realm(&child, |engine| run_in(engine, source))
                    .unwrap_or_else(|_| panic!("register"));
            });
            engine.interp.gc_collect();
            assert_eq!(
                engine.interp.realms.len(),
                2,
                "{tier:?}, {kind}: live callback source"
            );
            run_in(&mut engine, "kept = null");
            engine.interp.gc_collect();
            engine.interp.gc_collect();
            assert_eq!(
                engine.interp.realms.len(),
                1,
                "{tier:?}, {kind}: unreachable source cycle"
            );
        }
    }
}

#[cfg(feature = "embed")]
#[test]
fn job_callback_queued_source_is_a_temporary_root() {
    let mut engine = Engine::new();
    engine.set_job_callback_script_caller_capture(true);
    engine.define_global("nothing", 0, |_ctx, _, _| Ok(Value::Undefined));
    // The child Realm's values live only in this helper frame (the collector scans the stack).
    crate::gc_test::in_frame(|| {
        engine.scope(|cx| {
            let main = cx.global_this();
            let child = cx.create_embed_realm();
            cx.member_set(&child, "main", main)
                .unwrap_or_else(|_| panic!("parent"));
            cx.with_embed_realm(&child, |ctx| {
                let result = ctx.eval_classic_script_interruptible(
                    "main.Promise.resolve().then(main.nothing);",
                );
                assert!(result.is_ok_and(|completion| completion.is_ok()));
            })
            .unwrap_or_else(|_| panic!("queue child callback"));
        });
    });
    engine.interp.gc_collect();
    assert_eq!(
        engine.interp.realms.len(),
        2,
        "queued source must survive GC"
    );
    engine.run_microtasks();
    engine.interp.gc_collect();
    engine.interp.gc_collect();
    assert_eq!(
        engine.interp.realms.len(),
        1,
        "finished callback must release its source"
    );
}

#[cfg(feature = "embed")]
#[test]
fn job_callback_context_is_restored_on_host_interruption() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        for thenable in [false, true] {
            let mut engine = Engine::new();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            engine.set_job_callback_script_caller_capture(true);
            define_arm_deadline(&mut engine);
            run_in(&mut engine, "var caught = 0, later = 0; function spin() { armDeadline(); try { while(true) {} } catch (_) { caught++; } }");
            let interrupt = engine.interrupt_handle();
            let source = if thenable {
                "Promise.resolve({then: spin}).then(() => later++);"
            } else {
                "Promise.resolve().then(spin).then(() => later++);"
            };
            let result = engine.eval_interruptible(source, false).expect("parse");
            assert!(
                matches!(
                    result,
                    ExecutionOutcome::Interrupted {
                        reason: InterruptReason::DeadlineExceeded
                    }
                ),
                "{tier:?}, thenable={thenable}"
            );
            assert!(
                engine.interp.script_entry.is_none(),
                "callback boundary restored"
            );
            interrupt.set_deadline(None);
            assert_eq!(run_in(&mut engine, "caught + ':' + later"), "0:0");
        }
    }
}

#[cfg(feature = "embed")]
#[test]
fn suspended_context_preserves_script_caller_across_await_and_yield() {
    fn caller_global<'s>(
        ctx: &mut Ctx<'s>,
        _this: Value<'s>,
        _args: &[Value<'s>],
    ) -> Result<Value<'s>, Value<'s>> {
        Ok(ctx.script_caller_global())
    }

    // RunSuspendedContext restores the suspended function's execution context,
    // not the Promise reaction / borrowed Generator.prototype.next that resumes it.
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        for kind in ["async", "generator", "async-generator"] {
            let mut engine = Engine::new();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            engine.define_global("callerGlobal", 0, caller_global);
            run_in(&mut engine, "globalThis.observed = []; globalThis.pending = new Promise(r => globalThis.release = r)");
            let child = engine.scope(|cx| {
                let main = cx.global_this();
                let child = cx.create_embed_realm();
                cx.member_set(&child, "main", main)
                    .unwrap_or_else(|_| panic!("publish parent"));
                cx.member_set(&main, "child", child)
                    .unwrap_or_else(|_| panic!("publish child"));
                crate::embed::Handle::new(cx, &child).expect("a handle to the child's global")
            });
            let source = match kind {
                "async" => {
                    r#"
                    globalThis.task = async function () {
                        main.observed.push(main.callerGlobal() === globalThis);
                        await main.pending;
                        main.observed.push(main.callerGlobal() === globalThis);
                        try { await Promise.reject(7); }
                        catch (_) { main.observed.push(main.callerGlobal() === globalThis); }
                        await 0;
                        main.observed.push(main.callerGlobal() === globalThis);
                    };
                "#
                }
                "generator" => {
                    r#"
                    globalThis.task = function* () {
                        main.observed.push(main.callerGlobal() === globalThis);
                        yield Object.getPrototypeOf([]) === Array.prototype;
                        main.observed.push(main.callerGlobal() === globalThis);
                        try { yield 0; }
                        finally { main.observed.push(main.callerGlobal() === globalThis); }
                    };
                "#
                }
                _ => {
                    r#"
                    globalThis.task = async function* () {
                        main.observed.push(main.callerGlobal() === globalThis);
                        await main.pending;
                        main.observed.push(main.callerGlobal() === globalThis);
                        yield Object.getPrototypeOf([]) === Array.prototype;
                        try { yield 0; }
                        finally { main.observed.push(main.callerGlobal() === globalThis); }
                    };
                "#
                }
            };
            engine
                .with_embed_realm(&child, |engine| run_in(engine, source))
                .unwrap_or_else(|_| panic!("initialize child"));
            let expected = match kind {
                "async" => {
                    run_in(&mut engine, "child.task(); release();");
                    "true,true,true,true"
                }
                "generator" => {
                    run_in(
                        &mut engine,
                        r#"
                        const it=child.task(), proto=Object.getPrototypeOf(function*(){}.prototype);
                        function next() { return proto.next.call(it); }
                        observed.push(next().value); next(); proto.return.call(it);
                    "#,
                    );
                    "true,true,true,true"
                }
                _ => {
                    run_in(
                        &mut engine,
                        r#"
                        const it=child.task(), proto=Object.getPrototypeOf(async function*(){}.prototype);
                        proto.next.call(it).then(r=>observed.push(r.value)); release();
                    "#,
                    );
                    run_in(&mut engine, "proto.next.call(it);");
                    run_in(&mut engine, "proto.return.call(it);");
                    "true,true,true,true"
                }
            };
            assert_eq!(
                run_in(&mut engine, "observed.join(',')"),
                expected,
                "{tier:?} {kind}"
            );
            assert_eq!(
                run_in(&mut engine, "callerGlobal() === globalThis"),
                "true",
                "caller restored"
            );
        }
    }
}

#[cfg(feature = "embed")]
#[test]
fn suspended_context_realm_is_traced_but_not_permanently_rooted() {
    for tier in [
        crate::bytecode::Tier::Interp,
        crate::bytecode::Tier::Bytecode,
        crate::bytecode::Tier::Jit,
    ] {
        let mut engine = Engine::new();
        engine.set_tier(tier);
        engine.set_tier_threshold(0);
        // Strong handles live only in this helper frame (the collector scans the stack).
        crate::gc_test::in_frame(|| {
            let child = engine.scope(|cx| {
                let child = cx.create_embed_realm();
                crate::embed::Handle::new(cx, &child).expect("a handle to the child's global")
            });
            engine.with_embed_realm(&child, |engine| {
                run_in(engine, "globalThis.saved = (function* () { yield Object.getPrototypeOf([]) === Array.prototype; })()");
            }).unwrap_or_else(|_| panic!("initialize child continuation"));
            engine.scope(|cx| {
                let child = child.get(cx).expect("the engine's handle");
                let continuation = cx
                    .member_get(&child, "saved")
                    .unwrap_or_else(|_| panic!("read continuation"));
                let main = cx.global_this();
                cx.member_set(&main, "kept", continuation)
                    .unwrap_or_else(|_| panic!("retain continuation"));
            });
        });
        engine.interp.gc_collect();
        assert_eq!(
            engine.interp.realms.len(),
            2,
            "{tier:?}: live context must retain its intrinsics"
        );
        assert_eq!(run_in(&mut engine, "kept.next().value"), "true", "{tier:?}");
        // No completion is necessary: unreachable suspended generators and their
        // global -> generator -> context -> global cycle must be collectable.
        run_in(&mut engine, "kept = null");
        engine.interp.gc_collect();
        engine.interp.gc_collect();
        assert_eq!(
            engine.interp.realms.len(),
            1,
            "{tier:?}: dead context must not retain the Realm"
        );
        assert!(
            engine.interp.generators.is_empty(),
            "{tier:?}: dead coroutine must be reclaimed"
        );
    }
}

#[cfg(feature = "embed")]
#[test]
fn embedder_buffer_source_bytes_honor_views_detachment_and_shared_opt_in() {
    let mut engine = Engine::new();
    engine.scope(|cx| {
        let evaluated = cx
            .eval_value_interruptible(
                "globalThis.ab = new ArrayBuffer(6);\
                 globalThis.dv = new DataView(ab, 1, 3);\
                 dv.setUint8(0, 11); dv.setUint8(1, 22); dv.setUint8(2, 33);\
                 globalThis.ta = new Uint8Array(ab, 2, 2);\
                 globalThis.sab = new SharedArrayBuffer(4);\
                 globalThis.sta = new Uint8Array(sab); sta.set([4, 5, 6, 7]);",
            )
            .expect("parse");
        assert!(evaluated.is_ok(), "BufferSource setup threw");

        let global = cx.global_this();
        let mut get = |name: &str| {
            cx.member_get(&global, name)
                .unwrap_or_else(|_| panic!("read {name}"))
        };
        let (ab, dv, ta, sab, sta) = (get("ab"), get("dv"), get("ta"), get("sab"), get("sta"));

        assert_eq!(
            cx.buffer_source_bytes(&ab, false),
            Some(vec![0, 11, 22, 33, 0, 0])
        );
        assert_eq!(cx.buffer_source_bytes(&dv, false), Some(vec![11, 22, 33]));
        assert_eq!(cx.buffer_source_bytes(&ta, false), Some(vec![22, 33]));
        assert_eq!(cx.buffer_source_bytes(&sab, false), None);
        assert_eq!(cx.buffer_source_bytes(&sta, false), None);
        assert_eq!(cx.buffer_source_bytes(&sab, true), Some(vec![4, 5, 6, 7]));
        assert_eq!(cx.buffer_source_bytes(&sta, true), Some(vec![4, 5, 6, 7]));

        let transferred = cx
            .eval_value_interruptible("ab.transfer()")
            .expect("transfer parses");
        assert!(transferred.is_ok(), "ArrayBuffer transfer threw");
        assert_eq!(cx.buffer_source_bytes(&ab, false), None);
        assert_eq!(cx.buffer_source_bytes(&dv, false), None);
        assert_eq!(cx.buffer_source_bytes(&ta, false), None);
    });
}

#[cfg(feature = "embed")]
#[test]
fn embedder_buffer_source_bytes_follow_data_view_bounds() {
    // A DataView's bytes are its own range of the current backing store: length-tracking views
    // follow resizes, a fixed view past the shrunk end is out of bounds, and a shared view needs
    // [AllowShared].
    let mut engine = Engine::new();
    engine.scope(|cx| {
        let evaluated = cx
            .eval_value_interruptible(
                "globalThis.rb = new ArrayBuffer(8, {maxByteLength: 16});\
                 new Uint8Array(rb).set([0, 1, 2, 3, 4, 5, 6, 7]);\
                 globalThis.tracking = new DataView(rb, 5);\
                 globalThis.fixed = new DataView(rb, 4, 3);\
                 globalThis.sdv = new DataView(new SharedArrayBuffer(4), 1, 2);\
                 sdv.setUint8(0, 9); sdv.setUint8(1, 8);",
            )
            .expect("parse");
        assert!(evaluated.is_ok(), "DataView setup threw");
        let global = cx.global_this();
        let mut get = |name: &str| {
            cx.member_get(&global, name)
                .unwrap_or_else(|_| panic!("read {name}"))
        };
        let (tracking, fixed, sdv) = (get("tracking"), get("fixed"), get("sdv"));
        assert_eq!(
            cx.buffer_source_bytes(&tracking, false),
            Some(vec![5, 6, 7])
        );
        assert_eq!(cx.buffer_source_bytes(&fixed, false), Some(vec![4, 5, 6]));
        assert_eq!(cx.buffer_source_bytes(&sdv, false), None);
        assert_eq!(cx.buffer_source_bytes(&sdv, true), Some(vec![9, 8]));
        assert!(cx
            .eval_value_interruptible("rb.resize(6)")
            .expect("resize parses")
            .is_ok());
        assert_eq!(cx.buffer_source_bytes(&tracking, false), Some(vec![5]));
        assert_eq!(cx.buffer_source_bytes(&fixed, false), None);
    });
}

#[cfg(feature = "embed")]
#[test]
fn embedder_can_mirror_and_detach_an_array_buffer() {
    let mut engine = Engine::new();
    engine.scope(|cx| {
        let buffer = cx
            .make_array_buffer(&[1, 2, 3, 4])
            .unwrap_or_else(|_| panic!("make ArrayBuffer"));
        let global = cx.global_this();
        cx.member_set(&global, "mirrored", buffer)
            .unwrap_or_else(|_| panic!("install ArrayBuffer"));

        assert_eq!(
            cx.eval_value_interruptible("new Uint8Array(mirrored)[2]")
                .expect("view parses")
                .unwrap_or(Value::Undefined)
                .as_num_opt(),
            Some(3.0)
        );
        assert!(cx.array_buffer_set_bytes(&buffer, &[9, 8, 7, 6]));
        let version = cx
            .array_buffer_version(&buffer)
            .expect("attached buffer version");
        assert_eq!(
            cx.buffer_source_bytes(&buffer, false),
            Some(vec![9, 8, 7, 6])
        );
        assert!(cx
            .eval_value_interruptible("new Uint8Array(mirrored)[0] = 4")
            .expect("view write parses")
            .is_ok());
        assert_ne!(
            cx.array_buffer_version(&buffer),
            Some(version),
            "JavaScript writes advance the embedder mutation generation"
        );
        assert!(!cx.array_buffer_set_bytes(&buffer, &[1, 2]));
        assert!(cx.detach_array_buffer(&buffer));
        assert!(!cx.detach_array_buffer(&buffer));
        assert_eq!(cx.buffer_source_bytes(&buffer, false), None);
        assert_eq!(
            cx.eval_value_interruptible("mirrored.byteLength")
                .expect("byteLength parses")
                .unwrap_or(Value::Undefined)
                .as_num_opt(),
            Some(0.0)
        );
    });
}

#[cfg(feature = "embed")]
#[test]
fn embedder_keyed_array_buffer_rejects_script_transfer() {
    let mut engine = Engine::new();
    engine.scope(|cx| {
        let buffer = cx
            .make_host_keyed_array_buffer(&[1, 2, 3, 4])
            .unwrap_or_else(|_| panic!("make keyed ArrayBuffer"));
        let global = cx.global_this();
        cx.member_set(&global, "keyed", buffer)
            .unwrap_or_else(|_| panic!("install keyed ArrayBuffer"));

        let transfer = cx
            .eval_value_interruptible("keyed.transfer()")
            .expect("transfer parses");
        assert!(transfer.is_err());
        assert_eq!(
            cx.buffer_source_bytes(&buffer, false),
            Some(vec![1, 2, 3, 4])
        );
        assert!(cx.detach_array_buffer(&buffer));
        assert_eq!(cx.buffer_source_bytes(&buffer, false), None);
    });
}

#[cfg(feature = "embed")]
#[test]
fn embedder_array_buffers_never_run_author_code() {
    // A replaced global ArrayBuffer neither observes nor substitutes host-created buffers.
    let mut engine = Engine::new();
    engine.scope(|cx| {
        cx.eval_value_interruptible(
            "globalThis.calls = 0; globalThis.ArrayBuffer = function () { calls++; return {}; };",
        )
        .expect("replacement parses")
        .unwrap_or_else(|_| panic!("replace ArrayBuffer"));
        let plain = cx
            .make_array_buffer(&[1, 2, 3])
            .unwrap_or_else(|_| panic!("make ArrayBuffer"));
        let keyed = cx
            .make_host_keyed_array_buffer(&[4, 5])
            .unwrap_or_else(|_| panic!("make keyed ArrayBuffer"));
        let global = cx.global_this();
        for (name, buffer) in [("plain", plain), ("keyed", keyed)] {
            cx.member_set(&global, name, buffer)
                .unwrap_or_else(|_| panic!("install buffer"));
        }
        let result = cx
            .eval_value_interruptible(
                "calls + ',' + new Uint8Array(plain).join('') + ',' + new Uint8Array(keyed).join('') + ',' +\
                 (Object.getPrototypeOf(plain) === Object.getPrototypeOf(keyed)) + ',' + keyed.resizable",
            )
            .expect("probe parses")
            .unwrap_or(Value::Undefined);
        assert_eq!(result.as_text().as_deref(), Some("0,123,45,true,false"));
        assert_eq!(cx.buffer_source_bytes(&keyed, false), Some(vec![4, 5]));
    });
}

