#[cfg(not(target_arch = "wasm32"))]
#[test]
fn execution_stack_checkpoints_never_grow_past_the_segment_cap() {
    // A call path checks for exhaustion, then reaches its growth checkpoint at the same depth a
    // little deeper on the stack. At the segment cap a check inside the margin above the red zone
    // reports exhaustion, and a checkpoint that finds the red zone reached runs the call on the
    // current stack instead of adding a segment past the cap. The stack is positioned exactly,
    // in a thread of its own, and the live segment count set without allocating the segments.
    use crate::interpreter::{
        execution_stack_capped_checkpoints, execution_stack_exhausted, execution_stack_segments,
        with_execution_stack, with_execution_stack_segments, EXECUTION_STACK_CHECK_MARGIN,
        EXECUTION_STACK_RED_ZONE, MAX_EXECUTION_STACK_SEGMENTS,
    };
    const CAP: usize = MAX_EXECUTION_STACK_SEGMENTS;
    /// Run `f` deeper on this stack, in the first frame whose headroom is below `below`.
    #[inline(never)]
    fn below_headroom(below: usize, f: &mut dyn FnMut(usize)) {
        let mut frame = [0u8; 1024];
        std::hint::black_box(&mut frame);
        let remaining = stacker::remaining_stack().expect("a thread stack of known bounds");
        if remaining < below {
            f(remaining);
        } else {
            below_headroom(below, f);
        }
        std::hint::black_box(&frame);
    }
    std::thread::Builder::new()
        .name(String::from("trust-js-execution-stack-segment-cap"))
        .stack_size(4 * 1024 * 1024)
        .spawn(|| {
            // Inside the margin, above the red zone: exhausted at the cap only.
            let margin = EXECUTION_STACK_RED_ZONE + EXECUTION_STACK_CHECK_MARGIN / 2;
            below_headroom(margin, &mut |remaining| {
                assert!(remaining > EXECUTION_STACK_RED_ZONE + EXECUTION_STACK_CHECK_MARGIN / 4);
                with_execution_stack_segments(CAP - 1, || {
                    assert!(!execution_stack_exhausted(8), "below the cap");
                });
                with_execution_stack_segments(CAP, || {
                    assert!(execution_stack_exhausted(8), "inside the margin at the cap");
                });
            });
            // Inside the red zone: a checkpoint below the cap adds a segment, one at the cap
            // runs the call where it is.
            below_headroom(EXECUTION_STACK_RED_ZONE / 2, &mut |_| {
                with_execution_stack_segments(CAP - 1, || {
                    assert_eq!(with_execution_stack(8, execution_stack_segments), CAP);
                    assert_eq!(execution_stack_segments(), CAP - 1);
                });
                with_execution_stack_segments(CAP, || {
                    let capped = execution_stack_capped_checkpoints();
                    assert_eq!(with_execution_stack(8, execution_stack_segments), CAP);
                    assert_eq!(execution_stack_capped_checkpoints(), capped + 1);
                });
            });
            assert_eq!(execution_stack_segments(), 0);
        })
        .expect("spawn segment-cap test")
        .join()
        .expect("segment-cap test completes");
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn execution_stack_growth_checks_before_large_native_frames_exhaust_small_host_stack() {
    // ECMA-262 §9.4 makes execution contexts a specification mechanism rather than native Rust
    // stack frames. Model the relatively large native frames that accessors/host calls can place
    // between a small number of JS contexts: the growth checkpoint must engage before a normal
    // 2 MiB worker/test stack reaches its guard page.
    fn descend(depth: u32) -> u32 {
        let mut native_frame = [0u8; 96 * 1024];
        native_frame[0] = depth as u8;
        native_frame[native_frame.len() - 1] = depth as u8;
        let result = crate::interpreter::with_execution_stack(depth, || {
            if depth == 24 {
                depth
            } else {
                descend(depth + 1)
            }
        });
        std::hint::black_box(&native_frame);
        result
    }

    let depth = std::thread::Builder::new()
        .name(String::from("trust-js-early-stack-growth-check"))
        .stack_size(2 * 1024 * 1024)
        .spawn(|| descend(1))
        .expect("spawn early stack-growth test")
        .join()
        .expect("early stack-growth test completes");
    assert_eq!(depth, 24);
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn execution_stack_headroom_queries_are_amortized() {
    let before = crate::interpreter::execution_stack_checks();
    for depth in 1..=1_024 {
        crate::interpreter::with_execution_stack(depth, || ());
    }
    let checks = crate::interpreter::execution_stack_checks() - before;
    assert_eq!(checks, 129, "entry plus one check per eight contexts");
}

fn assert_deep_execution_contexts(tier: crate::bytecode::Tier) {
    // ECMA-262 §9.4 and §10.2.1 push a new execution context for an ECMAScript function
    // call; they do not insert an implementation-defined depth check into [[Call]]. Exercise
    // substantially more contexts than fit on this deliberately small native thread stack so
    // every execution tier has to keep the language stack independently of that host stack.
    const DEPTH: usize = 4_096;
    let value = std::thread::Builder::new()
        .name(format!("trust-js-deep-execution-contexts-{tier:?}"))
        .stack_size(8 * 1024 * 1024)
        .spawn(move || {
            let mut engine = Engine::new();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            match engine
                .eval(
                    &format!(
                        "function recurse(n){{return n===0 ? 0 : 1+recurse(n-1)}} recurse({DEPTH})"
                    ),
                    false,
                )
                .expect("deep-recursion fixture parses")
            {
                Completion::Value(value) => value,
                Completion::Throw { name, message } => {
                    panic!("{tier:?} rejected a valid call sequence: {name}: {message}")
                }
            }
        })
        .expect("spawn deep-execution-context test")
        .join()
        .expect("deep-execution-context test completes");
    assert_eq!(value, DEPTH.to_string(), "tier {tier:?}");
}

