    assert_eq!(run("'abcabc'.lastIndexOf('b',3)"), "1");
    assert_eq!(run("'abcabc'.lastIndexOf('x')"), "-1");
    assert_eq!(run("'canal'.lastIndexOf('a')"), "3");
    assert_eq!(run("'hello'.lastIndexOf('')"), "5");
    assert_eq!(run("'ABC'.toLocaleLowerCase()"), "abc");
